NAME = 'DaOT1871NT1907: Danish OT1871 + NT1907 with original orthography'
BOOK = 'Judges'

CHAPTERS = {
    1: {
        1: 'Og det skete efter Josvas Død, da adspurgte Israels Børn Herren og sagde: Hvo skal først drage op af os imod Kananiterne, til at stride imod dem?',
        2: 'Og Herren sagde: Juda skal drage op; se, jeg har givet Landet i hans Haand.',
        3: 'Da sagde Juda til Simeon sin Broder: Drag op med mig til min Lod, saa ville vi stride imod Kananiterne, saa vil jeg ogsaa gaa med dig til din Lod; saa gik Simeon med ham.',
        4: 'Og Juda drog op, og Herren gav Kananiterne og Feresiterne i deres Haand, og de sloge dem i Besek, ti Tusinde Mand.',
        5: 'Og de fandt Adoni-Besek i Besek og strede imod ham, og de sloge Kananiterne og Feresiterne.',
        6: 'Men Adoni-Besek flyede, og de forfulgte ham; og de grebe ham og afhuggede hans Tommelfingre og hans Tommeltæer.',
        7: 'Da sagde Adoni-Besek: Halvfjerdsindstyve Konger, hvis Tommelfingre og Tommeltæer vare afhugne, sankede op under mit Bord; som jeg har gjort, saa har Gud betalt mig; og de førte ham til Jerusalem, og der døde han.',
        8: 'Og Judas Børn strede imod Jerusalem og indtoge den og sloge den med skarpe Sværd og satte Ild paa Staden.',
        9: 'Derefter droge Judas Børn ned for at stride imod Kananiterne, som boede paa Bjerget og imod Sønden og i Lavlandet.',
        10: 'Og Juda drog hen imod Kananiterne, som boede i Hebron, og Hebrons Navn var fordum Kirjath-Arba, og de sloge Sesai, Ahiman og Talmai.',
        11: 'Og han drog derfra mod Debirs Indbyggere; og Debirs Navn var fordum Kirjath-Sefer.',
        12: 'Og Kaleb sagde: Hvo der slaar Kirjath-Sefer og indtager den, ham vil jeg give Aksa, min Datter, til Hustru.',
        13: 'Da indtog Othniel, en Søn af Kenas, Kalebs yngre Broder, den; og han gav ham Aksa, sin Datter, til Hustru.',
        14: 'Og det skete, der hun kom, da tilskyndte hun ham til at begære af hendes Fader en Ager, og hun sprang ned af Asenet; da sagde Kaleb til hende: Hvad fattes dig?',
        15: 'Og hun sagde til ham: Giv mig en Velsignelse, thi du har givet mig et Land mod Sønden, giv mig og Vandkilder; da gav Kaleb hende de øvre Vandkilder og de nedre Vandkilder.',
        16: 'Og Keniterens, Mose Svigerfaders, Børn droge op fra Palmestaden med Judas Børn til Judas Ørk, som er Sønden for Arad, og gik hen og boede der hos Folket.',
        17: 'Og Juda drog ud med sin Broder Simeon, og de sloge Kananiten, som boede i Zefat; og de bandlyste den, og man kaldte Stadens Navn Horma.',
        18: 'Og Juda indtog Gaza og dens Landemærke og Askion og dens Landemærke og Ekron og dens Landemærke.',
        19: 'Og Herren var med Juda, saa han fordrev dem, som boede paa Bjerget; men han mægtede ikke at fordrive Indbyggerne i Dalen, fordi de havde Jernvogne.',
        20: 'Og de gave Kaleb Hebron, som Mose havde sagt, og han fordrev derfra de tre Anaks Sønner.',
        21: 'Og Benjamins Børn fordreve ikke Jebusiten, som boede i Jerusalem; men Jebusiten boede hos Benjamins Børn i Jerusalem indtil denne Dag.',
        22: 'Og Josefs Hus drog ogsaa op imod Bethel, og Herren var med dem.',
        23: 'Og Josefs Hus bespejdede Bethel; men Stadens Navn var fordum Lus.',
        24: 'Og de, som holdt Vagt, saa en Mand, som gik ud af Staden; og de sagde til ham: Vis os, kære, hvor vi kunne komme ind i Staden, da ville vi bevise dig Miskundhed.',
        25: 'Og der han havde vist dem, hvor de kunde komme ind i Staden, da sloge de Staden med skarpe Sværd; men Manden og al hans Slægt lode de gaa.',
        26: 'Da gik Manden til Hethiternes Land, og han byggede en Stad og kaldte dens Navn Lus, det er dens Navn indtil denne Dag.',
        27: 'Og Manasse fordrev ikke Indbyggerne i Beth-Sean med dens tilhørende Stæder eller i Thaanak med dens tilhørende Stæder eller Indbyggerne i Dor med dens tilhørende Stæder eller Indbyggerne i Jibleam med dens tilhørende Stæder eller Indbyggerne i Megiddo med dens tilhørende Stæder; og Kananiten boede roligt i det samme Land.',
        28: 'Og det skete, der Israel blev stærk, da gjorde han Kananiten skatskyldig; men han fordrev ham ikke aldeles.',
        29: 'Og Efraim fordrev ikke Kananiten, som boede i Geser; men Kananiten boede midt iblandt dem i Geser.',
        30: 'Sebulon fordrev ikke Indbyggerne i Kitron eller Indbyggerne i Nahalol; men Kananiten boede midt iblandt dem og blev skatskyldig.',
        31: 'Aser fordrev ikke Indbyggerne i Akko eller Indbyggerne i Zidon og Alab og Aksib og Helba og Afik og Rehob.',
        32: 'Og Aseriterne boede iblandt Kananiterne, Landets Indbyggere; thi de fordreve dem ikke.',
        33: 'Nafthali fordrev ikke Indbyggerne i Beth-Semes eller Indbyggerne i Beth-Anath, men boede midt iblandt Kananiterne, som boede i Landet; men Indbyggerne i Beth-Semes og Beth-Anath bleve dem skatskyldige.',
        34: 'Og Amoriterne trængte Dans Børn hen til Bjerget; thi de tilstedte dem ikke at komme ned i Dalen.',
        35: 'Og Amoriterne boede roligt i Har-Heres, i Ajalon og i Saalbim; dog var Josefs Huses Haand dem svar; og de bleve skatskyldige.',
        36: 'Og Amoriternes Landemærke var fra Opgangen til Akrabbim, fra Klippen og op efter.',
    },
    2: {
        1: 'Og Herrens Engel kom op fra Gilgal til Bokim og sagde: Jeg har ført eder op af Ægypten og bragt eder i det Land, som jeg tilsvor eders Fædre, og jeg sagde: Jeg vil ikke rygge min Pagt med eder i Evighed.',
        2: 'Og I skulle ikke gøre Pagt med dette Lands Indbyggere, I skulle nedbryde deres Altre; men I hørte ikke min Røst; hvad er det, I have gjort?',
        3: 'Da sagde jeg ogsaa: Jeg vil ikke uddrive dem fra eders Ansigt; men de skulle være eder paa Siderne, og deres Guder skulle være eder til en Snare.',
        4: 'Og det skete, der Herrens Engel havde talet disse Ord til alle Israels Børn, da opløftede Folket sin Røst, og de græd.',
        5: 'Og de kaldte det samme Steds Navn Bokim, og de ofrede til Herren der.',
        6: 'Og der Josva lod Folket fare, og Israels Børn gik hver til sin Arv for at eje Landet,',
        7: 'da tjente Folket Herren, saa længe Josva levede, og saa længe de ældste levede, som levede længe efter Josva, hvilke havde set al Herrens store Gerning, som han havde gjort imod Israel.',
        8: 'Men der Josva, Nuns Søn, Herrens Tjener, var død, hundrede og ti Aar gammel,',
        9: 'og de havde begravet ham i hans Arvs Landemærke, i Thimnat-Heres, paa Efraims Bjerg, Norden for det Bjerg Gaas,',
        10: 'og der hele den samme Slægt ogsaa var forsamlet til sine Fædre, da kom en anden Slægt op efter dem, som ikke kendte Herren, ej heller den Gerning, som han havde gjort mod Israel.',
        11: 'Da gjorde Israels Børn det onde for Herrens Øjne, og de tjente Baalerne.',
        12: 'Og de forlode Herren deres Fædres Gud, som havde udført dem af Ægyptens Land, og vandrede efter andre Guder; af de Folks Guder, som vare trindt omkring dem, og tilbade dem; og de opirrede Herren.',
        13: 'Og de forlode Herren og tjente Baal og Astharoth.',
        14: 'Saa optændtes Herrens Vrede over Israel, og han gav dem i Røveres Haand, og disse røvede fra dem; og han solgte dem i deres Fjenders Haand trindt omkring, og de kunde ikke ydermere bestaa for deres Fjenders Ansigt.',
        15: 'I alt det, som de udgik til, var Herrens Haand imod dem til det onde, som Herren havde sagt, og som Herren havde svoret dem; og de bleve saare ængstede.',
        16: 'Og Herren oprejste Dommere, og de frelste dem af deres Røveres Haand.',
        17: 'Men de vare heller ikke deres Dommere lydige, thi de bolede med andre Guder og tilbade dem; de vege snart fra den Vej, som deres Fædre havde vandret paa ved at lyde Herrens Bud, de gjorde ikke saaledes.',
        18: 'Og naar Herren oprejste dem Dommere, da var Herren med Dommeren, og han frelste dem af deres Fjenders Haand, saa længe den Dommer levede; thi Herren ynkedes over dem for deres Suk over dem, som trængte dem og fortrykte dem.',
        19: 'Men det skete, naar Dommeren døde, da vendte de om og gjorde værre end deres Fædre ved at vandre efter andre Guder, at tjene dem og at tilbede dem; de lode ikke af fra deres Gerninger eller fra deres haarde Vej.',
        20: 'Og Herrens Vrede optændtes over Israel, og han sagde: Efterdi dette Folk har overtraadt min Pagt, som jeg har budt deres Fædre, og de løde ikke min Røst,',
        21: 'da vil jeg heller ikke ydermere fordrive fra deres Ansigt nogen af Hedningerne, som Josva efterlod, der han døde,',
        22: 'for at forsøge Israel ved dem, om de vilde tage Vare paa Herrens Vej, at vandre paa den, ligesom deres Fædre toge Vare derpaa, eller ej.',
        23: 'Saa lod Herren disse Hedninger blive, saa at han ikke snart fordrev dem; og han havde ikke givet dem i Josvas Haand.',
    },
    3: {
        1: 'Og disse ere de Hedninger, som Herren lod blive for ved dem at forsøge alle dem af Israel, som ikke vidste noget af alle Krigene med Kanaan;',
        2: 'kun for at Israels Børns Slægter kunde lære at forstaa sig paa Krig, kun de, som ikke tilforn havde kendt dertil:',
        3: 'Filisternes fem Fyrster og alle Kananiterne, og Sidonierne og Heviterne, som boede paa Libanons Bjerg fra Bjerget Baal-Hermon, indtil man kommer til Hamath.',
        4: 'Og de bleve for at forsøge Israel ved dem, for at faa at vide, om de vilde lyde Herrens Bud, hvilke han havde budt deres Fædre ved Mose.',
        5: 'Og Israels Børn boede midt iblandt Kananiterne, Hethiterne og Amoriterne og Feresiterne og Heviterne og Jebusiterne.',
        6: 'Og de toge sig deres Døtre til Hustruer, og deres Døtre gave de til deres Sønner, og de tjente deres Guder.',
        7: 'Og Israels Børn gjorde det, som var ondt for Herrens Øjne, og forglemte Herren deres Gud og tjente Baalerne og Astarterne.',
        8: 'Da optændtes Herrens Vrede over Israel, og han solgte dem i Kusan-Risathaims Haand, som var Konge i Aram Naharaim, og Israels Børn tjente Kusan-Risathaim otte Aar.',
        9: 'Da raabte Israels Børn til Herren, og Herren oprejste Israels Børn en Frelser, og han frelste dem, nemlig Othniel, en Søn af Kenas, Kalebs yngre Broder.',
        10: 'Og Herrens Aand var over ham, og han dømte Israel og drog ud til Krig, og Herren gav Kusan-Risathaim, Kongen af Aram, i hans Haand, og hans Haand var stærk over Kusan-Risathaim.',
        11: 'Og Landet havde Ro fyrretyve Aar; og Othniel, Kenas Søn, døde.',
        12: 'Men Israels Børn bleve ved at gøre det, som var ondt for Herrens Øjne, og Herren styrkede Eglon, Moabiternes Konge, imod Israel, fordi de gjorde det, som var ondt for Herrens Øjne.',
        13: 'Og han samlede til sig Ammons Børn og Amalek; og han gik hen og slog Israel, og indtoge Palmestaden.',
        14: 'Og Israels Børn tjente Eglon, Moabiternes Konge, atten Aar.',
        15: 'Da raabte Israels Børn til Herren, og Herren oprejste dem en Frelser, Ehud, Geras Søn, en Benjaminit, en Mand, som var kejthaandet; og Israels Børn sendte Eglon, Moabiternes Konge, Skænk ved hans Haand.',
        16: 'Og Ehud gjorde sig et Sværd, og det var tveægget, en Alen langt; og han spændte det under sine Klæder paa sin højre Hofte,',
        17: 'og han førte Skænken frem til Eglon, Moabiternes Konge; men Eglon var en saare fed Mand.',
        18: 'Og det skete, der han var færdig med at fremføre Skænken, da lod han Folket fare, som havde baaret Skænken.',
        19: 'Men han vendte tilbage fra Stenbrudene, som vare ved Gilgal, og han lod sige: Jeg har et hemmeligt Ord til dig, o Konge! Da sagde denne: Stille! og alle, som stode hos ham, gik ud fra ham.',
        20: 'Og Ehud kom ind til ham, og han sad ene i sin Sommersal, og Ehud sagde: Jeg har Guds Ord til dig; da stod han op af Tronen.',
        21: 'Og Ehud udrakte sin venstre Haand og tog Sværdet fra sin højre Hofte, og han stødte det i hans Bug.',
        22: 'Og Hæftet gik ogsaa ind efter Bladet, og Fedmen lukkede til efter Bladet; thi han drog ikke Sværdet ud af hans Bug, og Skarnet gik ud.',
        23: 'Da gik Ehud ud igennem Forsalen; og han tillukkede Salsdørene efter sig og lukkede dem i Laas.',
        24: 'Der han var gaaet ud, da kom hins Tjenere ind, og de saa, og se, Salsdørene vare lukkede i Laas; og de sagde: Han tildækker visseligen sine Fødder i Kammeret ved Sommersalen.',
        25: 'Og de ventede, indtil de skammede sig, og se, han oplukkede ikke Salsdørene; da toge de Nøglen og lukkede op, og se, da var deres Herre falden til Jorden og var død.',
        26: 'Men Ehud undkom, medens de tøvede; og han gik forbi Stenbrudene og undkom til Seirath.',
        27: 'Og det skete, der han kom derhen, da blæste han i Trompeten paa Efraims Bjerg; og Israels Børn droge ned med ham af Bjerget, og han gik foran dem.',
        28: 'Og han sagde til dem: Følger efter mig, thi Herren har givet eders Fjender Moabiterne i eders Haand; og de droge ned efter ham og indtoge Jordanens Færgesteder for Moab, og de lode ingen Mand gaa over.',
        29: 'Og de sloge Moabiterne paa den Tid, ved ti Tusinde Mænd, hver trivelig og hver kraftig Mand; og ikke een Mand undkom.',
        30: 'Saa bleve Moabiterne ydmygede paa den samme Dag under Israels Haand, og Landet havde Ro firsindstyve Aar.',
        31: 'Og efter ham var Samgar, Anaths Søn, og han slog Filisterne, seks Hundrede Mænd, med en Oksedriverstav; og han frelste ogsaa Israel.',
    },
    4: {
        1: 'Og Israels Børn bleve ved at gøre ondt for Herrens Øjne, der Ehud var død.',
        2: 'Og Herren solgte dem i Jabins, Kanaans Konges, Haand, som regerede i Hazor; og Sisera var hans Stridshøvedsmand, og han boede i Haroseth Hagojim.',
        3: 'Og Israels Børn raabte til Herren; thi han havde ni Hundrede Jernvogne, og han havde undertrykt Israels Børn med Magt tyve Aar.',
        4: 'Og Debora, en Kvinde, en Profetinde, Lapidoths Hustru, dømte Israel paa den samme Tid.',
        5: 'Og hun boede under Deboras Palmetræ, imellem Rama og Bethel, paa Efraims Bjerg; og Israels Børn gik op til hende for Retten.',
        6: 'Og hun sendte hen og lod kalde Barak, Abinoams Søn, af Kedes i Nafthali, og hun sagde til ham: Har ikke Herren Israels Gud budet: Gak og saml Folk paa Thabors Bjerg, og tag ti Tusinde Mænd med dig af Nafthali Børn og af Sebulons Børn.',
        7: 'Og jeg vil drage Sisera, Jabins Stridshøvedsmand, til dig, til Bækken Kison, og hans Vogne og hans Hob; og jeg vil give ham i din Haand.',
        8: 'Og Barak sagde til hende: Dersom du vil gaa med mig, da vil jeg gaa; men dersom du ikke vil gaa med mig, vil jeg ikke gaa.',
        9: 'Og hun sagde: Jeg vil visseligen gaa med dig; men du vil dog ikke faa Æren paa den Vej, som du gaar paa, thi Herren skal sælge Sisera i en Kvindes Haand; saa gjorde Debora sig rede og gik med Barak til Kedes.',
        10: 'Da kaldte Barak Sebulon og Nafthali sammen til Kedes; og der drog op efter ham ti Tusinde Mænd, og Debora drog op med ham.',
        11: 'Og Keniteren Heber havde skilt sig fra Keniterne, Hobabs, Mose Svigerfaders, Børn; og han slog sit Telt op indtil Lunden i Zaannaim, som er ved Kedes.',
        12: 'Da gave de Sisera til Kende, at Barak, Abinoams Søn, var dragen op paa Bjerget Thabor.',
        13: 'Og Sisera sammenkaldte alle sine Vogne, ni Hundrede Jernvogne, og alt Folket, som var med ham, fra Haroseth Hagojim til Bækken Kison.',
        14: 'Og Debora sagde til Barak: Staa op, thi dette er den Dag, paa hvilken Herren har givet Sisera i din Haand; er Herren ikke dragen ud for dit Ansigt? Saa drog Barak ned af Bjerget Thabor, og de ti Tusinde Mænd efter ham.',
        15: 'Da forfærdede Herren Sisera og alle Vognene og al Hæren ved skarpe Sværd for Baraks Ansigt; og Sisera steg af Vognen og flyede til Fods.',
        16: 'Men Barak forfulgte Vognene og Hæren indtil Haroseth Hagojim; og hele Siseras Lejr faldt for skarpe Sværd, der blev end ikke een tilovers.',
        17: 'Men Sisera flyede til Fods til Jaels, Keniteren Hebers Hustrus, Telt, thi der var Fred imellem Jabin, Kongen af Hazor, og imellem Keniteren Hebers Hus.',
        18: 'Da gik Jael ud imod Sisera og sagde til ham: Tag ind, min Herre! tag ind til mig, frygt ikke; og han tog ind til hende i Teltet, og hun dækkede ham til med et By.',
        19: 'Og han sagde til hende: Kære, giv mig lidt Vand at drikke, thi jeg tørster; da aabnede hun en Mælkeflaske og lod ham drikke og dækkede ham til.',
        20: 'Og han sagde til hende: Stil dig ved Døren af Teltet, og sker det, at der kommer nogen og spørger dig og siger: Er her nogen? da skal du sige: Her er ingen.',
        21: 'Da tog Jael, Hebers Hustru, en Teltnagel og tog en Hammer i sin Haand og gik ind til ham sagteligen og slog Naglen igennem hans Tinding, at den gik ned i Jorden (thi han sov haardt og var træt), og han døde.',
        22: 'Og se, der Barak forfulgte Sisera, da gik Jael ud imod ham og sagde til ham: Kom, saa vil jeg vise dig den Mand, som du søger efter; og han kom ind til hende, og se, Sisera laa der og var død, og Naglen sad i hans Tinding.',
        23: 'Saa ydmygede Gud paa den Dag Jabin, Kanaans Konge, for Israels Børns Ansigt.',
        24: 'Og Israels Børns Haand fik Fremgang og blev haard over Jabin, Kanaans Konge, indtil de fik Jabin, Kanaans Konge, udryddet.',
    },
    5: {
        1: 'Da sang Debora og Barak, Abinoams Søn, paa den Dag og sagde:',
        2: 'Lover Herren, fordi der er taget Hævn i Israel, der Folket var villigt dertil.',
        3: 'Hører, I Konger! mærker, I Fyrster! jeg vil synge for Herren; Herren, Israels Gud, vil jeg lovsynge.',
        4: 'Herre! der du uddrog fra Seir, der du gik frem fra Edoms Mark, da bævede Jorden, ogsaa Himlene dryppede, ja Skyerne dryppede med Vand.',
        5: 'Bjergene fløde hen for Herrens Ansigt, Sinai selv, for Herrens, Israels Guds, Ansigt.',
        6: 'I Samgars, Anaths Søns, Dage, i Jaels Dage vare Stierne tomme; og de vejfarende gik ad krogede Stier.',
        7: 'Landsbyerne i Israel vare tomme, de vare tomme, indtil jeg Debora stod frem, indtil jeg stod frem, en Moder i Israel.',
        8: 'Da man udvalgte nye Guder, da var der Krig i Portene; der blev ikke set Skjold eller Spyd iblandt fyrretyve Tusinde i Israel.',
        9: 'Mit Hjerte slaar for Israels Høvdinger, de som beviste sig villige iblandt Folket; lover Herren!',
        10: 'I, som ride paa hvide Aseninder, I, som sidde paa Tæpper, og I, som gaa paa Vejen, taler frit!',
        11: 'Skytternes Bøst lyder fra de Steder, hvor man drager Vand, der prise de Herrens Retfærdighed, Retfærdighed imod hans Landsbyer i Israel. Da steg Herrens Folk ned til Portene.',
        12: 'Vaagn op, vaagn op, Debora, vaagn op, vaagn op, istem en Sang! gør dig rede, Barak, og før dine Fanger fangne bort, du Abinoams Søn!',
        13: 'Da drog en Levning af de herlige, af Folket ned; Herren drog ned for mig blandt de vældige.',
        14: 'De af Efraim, som havde Bod i Amalek, stege ned efter dig Benjamin med dine Folk; af Makir nedstege Høvdinger og af Sebulon de, som føre Herskerstaven.',
        15: 'Ogsaa var der Fyrster af Isaskar med Debora, og som Isaskar saa Barak, i Dalen styrtede han frem! Ved Rubens Vandbække vare Hjertets Betænkninger store.',
        16: 'Hvorfor blev du imellem Faarestierne, at høre paa Hyrdefløjten? medens Ruben blev ved sine Vandbække, var der store Ransagninger i Hjertet.',
        17: 'Gilead blev boende paa hin Side Jordanen; og hvorfor blev Dan ved Skibene? Aser blev ved Havets Bred og blev boende ved sine Havbugter.',
        18: 'Sebulon var et Folk, som agtede sit Liv ringe indtil Døden, i lige Maade Nafthali, paa Markens høje Steder.',
        19: 'Kongerne kom, de strede; da strede Kanaans Konger udi Thaanak ved Megiddo Vand; de fik ingen Vinding af Sølv.',
        20: 'Fra Himmelen stredes der; Stjernerne fra deres høje Baner strede mod Sisera.',
        21: 'Bækken Kison bortfejede dem, de gamles Bæk, Bækken Kison; træd frem, min Sjæl, med Styrke!',
        22: 'Da trampede Hestenes Hove ved deres Heltes jagende, jagende Fart.',
        23: 'Forbander Meros, sagde Herrens Engel, forbander, forbander dens Indbyggere, fordi de ikke kom Herren til Hjælp, Herren til Hjælp iblandt de vældige.',
        24: 'Velsignes skal Jael, Keniteren Hebers Hustru, fremfor Kvinderne; velsignes skal hun fremfor Kvinderne i noget Paulun.',
        25: 'Han begærede Vand, hun gav Mælk; hun bar Fløde frem i de herliges Skaal.',
        26: 'Sin Haand rakte hun ud efter Naglen og sin højre Haand efter Smedehammeren; og hun slog Sisera, sønderslog hans Hoved og knuste og igennemstak hans Tinding.',
        27: 'Imellem hendes Fødder krummede han sig, faldt, laa; imellem hendes Fødder krummede han sig, faldt; hvor han krummede sig, der faldt han og var tilintetgjort.',
        28: 'Siseras Moder saa ud af Vinduet, og skreg overlydt igennem Sprinkelværket: Hvi tøver hans Vogn med at komme? hvi blive hans Vognhjul tilbage?',
        29: 'De vise iblandt hendes Fyrstinder svarede hende, ogsaa svarede hun sig selv paa sine Ord:',
        30: 'Skulde de ikke finde, ja uddele til Bytte en Pige, to Piger for hver Mand? for Sisera brogede Klæder til Bytte, brogede, stukne Klæder til Bytte? brogede, stukne paa begge Sider om Halsen, til Bytte?',
        31: 'Saa skulle, Herre! alle dine Fjender omkomme, men de, som elske ham, skulle være ligesom Solen, der gaar frem i sin Kraft. — Og Landet havde Ro fyrretyve Aar.',
    },
    6: {
        1: 'Og Israels Børn gjorde ondt for Herrens Øjne, og Herren gav dem i Midianiternes Haand syv Aar.',
        2: 'Og der Midianiternes Haand blev stærk over Israel, da gjorde Israels Børn sig Kløfter, som vare i Bjergene, og Huler og Befæstninger for Midianiternes Skyld.',
        3: 'Og det skete, naar Israel havde saaet, da kom Midianiterne og Amalekiterne op og de Folk af Østen, de kom op over dem.',
        4: 'Og de lejrede sig imod dem, og de ødelagde Landets Grøde, indtil man kommer til Gaza; og de lode ikke Føde blive tilovers i Israel, ej heller Faar eller Okse eller Asen.',
        5: 'Thi de kom op med deres Kvæg og deres Telte; de kom ligesom Græshopper i Mangfoldighed, saa at der ikke var Tal paa dem og deres Kameler; og de kom i Landet at ødelægge det.',
        6: 'Og Israel blev forarmet for Midianiternes Ansigt, og Israels Børn raabte til Herren.',
        7: 'Og det skete, der Israels Børn raabte til Herren for Midianiternes Skyld,',
        8: 'da sendte Herren en Mand, en Profet, til Israels Børn, og han sagde til dem: Saa siger Herren, Israels Gud: Jeg førte eder op af Ægypten og udførte eder af Trælles Hus.',
        9: 'Og jeg udfriede eder af Ægypternes Haand og af alle deres Haand, som trængte eder; og jeg uddrev dem fra eders Ansigt og gav eder deres Land.',
        10: 'Og jeg sagde til eder: Jeg er Herren eders Gud, frygter ikke Amoriternes Guder, i hvis Land I bo; men I have ikke været min Røst lydige.',
        11: 'Og Herrens Engel kom og satte sig under den Eg, som er i Ofra, som hørte Joas, den Abiesriter, til; og hans Søn Gideon tærskede Hvede i en Vinperse, at han kunde føre det hastig bort fra Midianiternes Ansigt.',
        12: 'Da aabenbaredes Herrens Engel for ham, og han sagde til ham: Herren være med dig, du vældige til Strid!',
        13: 'Men Gideon sagde til ham: Hør mig, min Herre! om Herren er med os, hvi har da alt dette ramt os? og hvor ere alle hans underlige Ting, som vore Fædre fortalte os og sagde: Førte Herren os ikke op af Ægypten? men nu har Herren forladt os og givet os i Midianiternes Haand.',
        14: 'Da vendte Herren sig til ham og sagde: Gaa hen i denne din Kraft, og du skal frelse Israel af Midianiternes Haand; har jeg ikke sendt dig?',
        15: 'Og han sagde til ham: Hør mig, Herre! hvormed skal jeg frelse Israel? se, min Slægt er den ringeste i Manasse, og jeg er den yngste i min Faders Hus.',
        16: 'Og Herren sagde til ham: Sandelig, jeg vil være med dig; og du skal slaa Midianiterne som een Mand.',
        17: 'Da sagde han til ham: Kære, dersom jeg har fundet Naade for dine Øjne, da gør mig et Tegn, at du er den, deltaler med mig.',
        18: 'Kære, vig ikke bort herfra, indtil jeg kommer til dig og bringer min Skænk og sætter den frem for dit Ansigt; og han sagde: Jeg vil blive, indtil du kommer tilbage.',
        19: 'Og Gideon kom og tilberedte et Gedekid og en Efa Mel til usyrede Kager, han lagde Kødet i en Kurv og kom Suppen i en Potte, og han førte det ud til ham under Egen og satte det frem.',
        20: 'Da sagde den Guds Engel til ham: Tag Kødet og de usyrede Kager og læg det paa denne Klippe og udøs Suppen; og han gjorde saaledes.',
        21: 'Da udrakte Herrens Engel det yderste af den Kæp, som han havde i sin Haand, og rørte ved Kødet og ved de usyrede Kager; og der udfor Ild af Klippen og fortærede Kødet og de usyrede Kager, og Herrens Engel for bort fra hans Øjne.',
        22: 'Der Gideon saa, at det var Herrens Engel, da sagde Gideon: Ak Herre, Herre! — thi derfor har jeg set Herrens Engel Ansigt til Ansigt.',
        23: 'Og Herren sagde til ham: Fred være med dig, frygt ikke, du skal ikke dø.',
        24: 'Da byggede Gideon Herren et Alter der og kaldte det: Herren er Fred; indtil denne Dag staar det endnu i Ofra, som hører Abiesriterne til.',
        25: 'Og det skete den samme Nat, at Herren sagde til ham: Tag en ung Okse, som er din Faders, og den anden syvaarige Okse, og du skal nedbryde Baals Alter, som er din Faders, og omhugge Astartebilledet, som staar derhos.',
        26: 'Og du skal bygge Herren din Gud et Alter oven paa denne stærke Klippe, hvor den er jævn; og du skal tage den anden Okse og ofre et Brændoffer ved Træet af Astartebilledet, som du skal omhugge.',
        27: 'Da tog Gideon ti Mænd af sine Tjenere og gjorde, som Herren havde sagt til ham; og det skete, eftersom han frygtede for sin Faders Hus og for Mændene i Staden at gøre det om Dagen, da gjorde han det om Natten.',
        28: 'Og Mændene i Staden stode aarle op om Morgenen, og se, da var Baals Alter nedbrudt, og Astartebilledet, som var derhos, var omhugget; og den anden Okse var ofret paa det byggede Alter.',
        29: "Da sagde den ene til den anden: Hvo har gjort denne Gerning? Og der de ransagede og eftersøgte, da sagde de: Gideon, Joas's Søn, har gjort denne Gerning.",
        30: 'Da sagde Mændene i Staden til Joas: Før din Søn hid, thi han skal dø, fordi han har nedbrudt Baals Alter, og fordi han har omhugget Astartebilledet, som var derhos.',
        31: 'Da sagde Joas til alle dem, som stode hos ham: Ville I stride for Baal? mon I ville frelse ham? hvo som strider for ham, han skal dødes inden Morgen; dersom han er Gud, da stride han for sig selv, fordi man nedbrød hans Alter.',
        32: 'Og man kaldte ham paa den Dag Jerub-Baal, idet man sagde: Baal stride imod ham, efterdi han har nedbrudt hans Alter.',
        33: 'Og alle Midianiterne og Amalekiterne og Folkene af Øster samledes til Hobe, og de droge over og sloge Lejr i Jisreels Dal.',
        34: 'Da iførte Herrens Aand sig Gideon, og han lod blæse i Trompeten, og Abiesers Slægt opbødes til at følge ham.',
        35: 'Og han sendte Bud til hele Manasse, og de bleve ogsaa opbudne til at følge ham; han sendte og Bud til Aser og til Sebulon og til Nafthali, og de kom dem i Møde.',
        36: 'Og Gideon sagde til Gud: Dersom du vil frelse Israel ved min Haand, ligesom du har sagt,',
        37: 'se, da lægger jeg et Uldskind i Gaarden; dersom der vorder Dug paa Uldskindet alene og tørt paa al Jorden, da ved jeg, at du vil frelse Israel ved min Haand, som du har sagt.',
        38: 'Og det skete saa; og der han stod anden Dag aarle op, da trykkede han Uldskindet ud og udkrystede Dug af Uldskindet, en Skaal fuld af Vand.',
        39: 'Og Gideon sagde til Gud: Lad din Vrede ikke optændes mod mig, at jeg taler alene denne Gang; kære, jeg vil ikkun forsøge det endnu denne Gang med Uldskindet; kære, lad være tørt paa Uldskindet alene, og lad Dug være paa al Jorden.',
        40: 'Og Gud gjorde det saaledes i den samme Nat, og der var tørt paa Uldskindet alene, og der var Dug paa al Jorden.',
    },
    7: {
        1: 'Da stod Jerub-Baal, det er Gideon, tidlig op, og alt Folket, som var med ham, og de lejrede sig ved Kilden Harod; og Midians Lejr var Norden for ham bag Højen More, i Dalen.',
        2: 'Og Herren sagde til Gideon: Folket, som er med dig, er flere, end at jeg skulde give Midianiterne i deres Haand, at Israel ikke skal rose sig mod mig og sige: Min Haand har frelst mig.',
        3: 'Saa udraab nu dog for Folkets Øren og sig: Hvo er frygtagtig og forskrækket? han vende tilbage og skynde sig aarle fra Gileads Bjerg; da vendte to og tyve Tusinde af Folket tilbage, og ti Tusinde bleve tilovers.',
        4: 'Og Herren sagde til Gideon: Folket er endnu for mange, før dem ned til Vandet, saa vil jeg der prøve det for dig; og det skal ske, den, om hvem jeg siger til dig: Denne skal gaa med dig, han skal gaa med dig; men hver den, om hvem jeg siger til dig: Denne skal ikke gaa med dig, han skal ikke gaa.',
        5: 'Og han førte Folket ned til Vandet, og Herren sagde til Gideon: Hver, som laber med sin Tunge af Vandet, som Hunden laber, ham skal du stille for sig, saa og hver, som bøjer sig paa sine Knæ at drikke.',
        6: 'Da var deres Tal, som havde labet af deres Haand til deres Mund, tre Hundrede Mænd; og det øvrige Folk alt sammen bøjede sig paa deres Knæ at drikke Vand.',
        7: 'Og Herren sagde til Gideon: Med de tre Hundrede Mænd, de som have labet, vil jeg frelse eder og give Midianiterne i din Haand; men alt det andet Folk maa gaa hver til sit Sted.',
        8: 'Og Folket tog Tæring med sig og deres Trompeter, men de andre Israeliter lod han alle fare, hver til sit Telt, og han beholdt de tre Hundrede Mænd hos sig, og Midianiternes Lejr var neden for ham i Dalen.',
        9: 'Og det skete i den samme Nat, at Herren sagde til ham: Staa op, gak ned mod Lejren; thi jeg har givet den i din Haand.',
        10: 'Men om du frygter for at gaa ned, da gaa du og Pura, din Dreng, ned til Lejren.',
        11: 'Og du skal høre, hvad de tale, og derefter skulle dine Hænder blive styrkede, og du skal drage ned mod Lejren; og han gik ned, han og Pura, hans Dreng, til det yderste af de bevæbnede, som vare i Lejren.',
        12: 'Og Midianiterne og Amalekiterne og alle Folk af Østen havde lagt sig ned i Dalen, som Græshopper i Mangfoldighed; og deres Kameler vare utallige som Sandet, der er paa Havets Bred, i Mangfoldighed.',
        13: 'Og Gideon kom, og se, da fortalte en Mand sin Næste en Drøm, og han sagde: Se, jeg drømte en Drøm, og se, et askebagt Bygbrød vendte sig hid og did i Midianiternes Lejr; og der det kom til Teltet, da slog det derpaa, saa at det faldt, og det kastede det over Ende, og Teltet faldt.',
        14: "Da svarede den anden og sagde: Det er intet andet end Gideons, den israelitiske Mands, Joas' Søns, Sværd; Gud har givet Midianiterne og den ganske Lejr i hans Haand.",
        15: 'Og det skete, der Gideon hørte Fortællingen og Udlæggelsen af Drømmen, da tilbad han; og han vendte tilbage til Israels Lejr og sagde: Staar op, thi Herren har givet Midianiternes Lejr i eders Haand.',
        16: 'Og han delte de tre Hundrede Mænd i tre Hobe; og han gav dem alle Trompeter i deres Haand og tomme Krukker og Blus midt udi Krukkerne.',
        17: 'Og han sagde til dem: I skulle se paa mig, og saaledes skulle I gøre; og se, naar jeg kommer til det yderste af Lejren, da skal det ske, at ligesom jeg vil gøre, saa skulle I gøre.',
        18: 'Og naar jeg blæser i Trompeten, jeg og hver, som er med mig, da skulle I ogsaa blæse i Trompeterne trindt omkring den ganske Lejr og sige: For Herren og for Gideon!',
        19: 'Saa kom Gideon og de hundrede Mænd, som vare med ham, til det yderste af Lejren i den midterste Vagts Begyndelse, de havde lige sat Vagten ud; og de blæste i Trompeterne og søndersloge Krukkerne, som vare i deres Haand.',
        20: 'Saa blæste de tre Hobe i Trompeterne og sønderbrøde Krukkerne, men de holdt Blussene fast i deres venstre Haand og Trompeterne i deres højre Haand til at blæse udi, og de raabte: Sværd for Herren og for Gideon!',
        21: 'Og de stode hver paa sit Sted omkring Lejren; da løb den ganske Lejr, og de skrege og flyede.',
        22: 'Og de blæste i de tre Hundrede Trompeter, og Herren satte den enes Sværd imod den anden og imod den ganske Lejr; og Lejren flyede til Beth-Sitta til Zerera, indtil Grænsen af Abel Mehola ved Tabbath.',
        23: 'Og Israels Mænd af Nafthali og af Aser og af hele Manasse bleve opbudne; og de forfulgte Midianiterne.',
        24: 'Og Gideon sendte Bud paa det ganske Efraims Bjerg og lod sige: Kommer ned imod Midianiterne og besætter Vandene for dem indtil Beth-Bara, og Jordanen; da blev opbudet hver Mand i Efraim, og de besatte Vandene indtil Beth-Bara og Jordanen.',
        25: 'Og de grebe to af Midianiternes Fyrster, Oreb og Seeb, og de dræbte Oreb paa Klippen Oreb, og Seeb dræbte de i Vinpersen Seeb, og de forfulgte Midianiterne; og de førte Orebs og Seebs Hoveder til Gideon hinsides Jordanen.',
    },
    8: {
        1: 'Og Mændene af Efraim sagde til ham: Hvad er det for en Ting, du har gjort os, at du ikke kaldte os, der du gik at stride imod Midianiterne? og de kivede stærkt med ham.',
        2: 'Og han sagde til dem: Hvad har jeg nu gjort som I? er ikke Efraims Efterhøst bedre end Abiesers Vinhøst?',
        3: 'Gud har givet Midianiternes Fyrster, Oreb og Seeb, i eders Haand, og hvad formaar jeg at gøre som I? Der han havde sagt det Ord, da lod deres Vrede af fra ham.',
        4: 'Der Gideon kom til Jordanen, gik han over og de tre Hundrede Mænd, som vare med ham, trætte af at forfølge.',
        5: 'Og han sagde til Mændene i Sukot: Kære, giver det Folk, som er i Følge med mig, nogle Brød; thi de ere trætte, og jeg forfølger Seba og Zalmuna, Midianiternes Konger.',
        6: 'Men de Øverste i Sukot sagde: Er da Sebas og Zalmunas Haand nu i din Haand, at vi skulle give din Hær Brød?',
        7: 'Og Gideon sagde: Derfor naar Herren giver Seba og Zalmuna i min Haand, da vil jeg tærske eders Kød med Torne af Ørken og med Tidsler.',
        8: 'Og han drog derfra op til Pnuel og talede til dem paa samme Maade; og Mændene i Pnuel svarede ham, ligesom Mændene i Sukot svarede.',
        9: 'Og han sagde ogsaa til Mændene i Pnuel saalunde: Naar jeg kommer tilbage med Fred, da vil jeg nedbryde dette Taarn.',
        10: 'Men Seba og Zalmuna vare i Karkor og med dem deres Lejr ved femten Tusinde, som vare alle de overblevne af den ganske Lejr af Folkene i Østen; men der var falden hundrede og tyve Tusinde Mænd, som kunde drage Sværd.',
        11: 'Og Gideon drog op ad deres Vej, som bo i Telte, Østen for Noba og Jogbea; og han slog den Lejr, thi Lejren var tryg.',
        12: 'Og Seba og Zalmuna flyede, men han forfulgte dem; og han greb de to Midianiternes Konger, Seba og Zalmuna, og forfærdede den ganske Lejr.',
        13: "Men der Gideon, Joas's Søn, kom tilbage fra Krigen fra Opgangen til Heres,",
        14: 'da greb han en ung Karl af Mændene i Sukot og adspurgte ham; og denne skrev op for ham de Øverste i Sukot og de Ældste sammesteds, halvfjerdsindstyve og syv Mænd.',
        15: 'Og han kom til Mændene i Sukot og sagde: Se, her er Seba og Zalmuna, med hvilke I forhaanede mig og sagde: Er da Sebas og Zalmunas Haand nu i din Haand, at vi skulle give dine Folk, som ere trætte, Brød?',
        16: 'Og han tog de Ældste af Staden og Torne af Ørken og Tidsler og lod Folket i Sukot faa Forstand ved dem.',
        17: 'Og Pnuels Taarn nedbrød han, og han ihjelslog Mændene i Staden.',
        18: 'Og han sagde til Seba og til Zalmuna: Hvordan vare de Mænd, som I sloge ihjel ved Thabor? og de sagde: Som du, saa vare de, hver af dem saa ud som en Kongesøn.',
        19: 'Og han sagde: De vare mine Brødre, min Moders Sønner: Saa vist som Herren lever, dersom I havde ladet dem leve, da vilde jeg ikke slaget eder ihjel.',
        20: 'Og han sagde til Jether, sin førstefødte: Staa op, slaa dem ihjel; men Drengen drog ikke sit Sværd ud, thi han frygtede, efterdi han var endnu en Dreng.',
        21: 'Men Seba og Zalmuna sagde: Staa du op og fald an paa os, thi som Manden er, saa er hans Styrke; saa stod Gideon op og slog Seba og Zalmuna ihjel og toge de Halvmaaner, som vare paa deres Kamelers Halse.',
        22: 'Da sagde hver Mand i Israel til Gideon: Hersk over os, baade du og saa din Søn, saa og din Søns Søn, efterdi du har frelst os af Midianiternes Haand.',
        23: 'Og Gideon sagde til dem: Jeg vil ikke herske over eder; og min Søn skal ikke herske over eder; Herren skal herske over eder.',
        24: 'Og Gideon sagde til dem: Jeg har en Begæring til eder: Hver give mig dog en Bing af hans Bytte; thi hine havde Guldringe, eftersom de vare Ismaeliter.',
        25: 'Og de sagde: Vi ville gerne give, og de bredte et Klæde ud; og de kastede hver en Bing af sit Bytte derpaa.',
        26: 'Og Vægten af de Guldringe, som han begærede, var tusinde og syv Hundrede Sekel Guld, foruden de Halvmaaner og de Halskæder og de Purpurklæder, som Midianiternes Konger havde paa sig, og foruden de Kæder, som vare om deres Kamelers Halse.',
        27: 'Og Gideon anvendte det til en Livkjortel og henlagde den i sin Stad udi Ofra, og al Israel bolede med den; og det blev Gideon og hans Hus til en Snare.',
        28: 'Saa bleve Midianiterne ydmygede for Israels Børn og bleve ikke ved at opløfte deres Hoved, og Landet havde Bo fyrretyve Aar i Gideons Dage.',
        29: "Og Jerub-Baal, Joas's Søn, gik bort og boede i sit Hus.",
        30: 'Og Gideon havde halvfjerdsindstyve Sønner, som vare udkomne af hans Lænd; thi han havde mange Hustruer.',
        31: 'Og hans Medhustru, som var i Sikem, fødte ham ogsaa en Søn; og han gav ham Navnet Abimelek.',
        32: "Og Gideon, Joas's Søn, døde i en god Alderdom, og han blev begraven udi sin Faders, Abiesriteren Joas's, Grav i Ofra.",
        33: 'Og det skete, der Gideon var død, da vendte Israels Børn om og bolede med Baalerne; og de gjorde sig Baal-Berith til en Gud.',
        34: 'Og Israels Børn kom ikke Herren, deres Gud, i Hu, som havde friet dem af alle deres Fjenders Haand trindt omkring.',
        35: 'Og de viste ikke Kærlighed mod Jerub-Baals, det er Gideons Hus, efter alt det gode, som han havde gjort mod Israel.',
    },
    9: {
        1: 'Og Abimelek, Jerub-Baals Søn, gik til Sikem til sin Moders Brødre og talede til dem og til al sin Morfaders Huses Slægt og sagde:',
        2: 'Kære, taler for alle Mændenes Øren udi Sikem: Hvilket er eder bedst, enten at halvfjerdsindstyve Mænd, alle Jerub-Baals Sønner, herske over eder? eller at een Mand hersker over eder? kommer og i Hu, at jeg er eders Ben og eders Kød.',
        3: 'Da talede hans Moders Brødre alle disse Ord om ham for alle Mændenes Øren i Sikem, og deres Hjerter bøjede sig efter Abimelek, thi de sagde: Han er vor Broder.',
        4: 'Og de gave ham 70 Sekel Sølv af Baal-Beriths Hus, og Abimelek lejede derfor løse og letfærdige Mænd, og de fulgte ham.',
        5: 'Og han kom til sin Faders Hus i Ofra og ihjelslog sine Brødre, Jerub-Baals Sønner, halvfjerdsindstyve Mænd, paa een Sten; men Jotham, Jerub-Baals yngste Søn, blev tilovers, thi han havde skjult sig.',
        6: 'Og alle Mændene i Sikem og det ganske Millo Hus forsamledes og gik hen og gjorde Abimelek til Konge ved den Lund, som staar ved Sikem.',
        7: 'Og man gav Jotham det til Kende, og han gik hen og stod paa Garizims Bjergs Top og opløftede sin Bøst og raabte og sagde til dem: Hører mig, I Mænd i Sikem, saa skal Gud høre eder!',
        8: 'Træerne gik engang hen for at salve en Konge over sig, og de sagde til Olietræet: Reger over os!',
        9: 'Og Olietræet sagde til dem: Skulde jeg forlade min Fedme, som Gud og Menneskene ære hos mig, og gaa hen at svæve over Træerne?',
        10: 'Da sagde Træerne til Figentræet: Kom du, reger over os!',
        11: 'Men Figentræet sagde til dem: Skulde jeg forlade min Sødme og min gode Frugt og gaa hen at svæve over Træerne?',
        12: 'Da sagde Træerne til Vinstokken: Kom du, reger over os!',
        13: 'Og Vinstokken sagde til dem: Skulde jeg forlade min Most, som glæder Guder og Mennesker, og gaa hen at svæve over Træerne?',
        14: 'Da sagde alle Træerne til Tornebusken: Kom du, reger over os!',
        15: 'Og Tornebusken sagde til Træerne: Er det i Sandhed saa, at I ville salve mig til Konge over eder, da kommer, skjuler eder under min Skygge; men hvis ikke, da komme Ild ud af Tornebusken og fortære Cedrene paa Libanon.',
        16: 'Og dersom I nu have handlet troligt og redeligt, ved at I have gjort Abimelek til Konge, og I have gjort godt imod Jerub-Baal og imod hans Hus, og I have gjort imod ham, som han har fortjent,',
        17: 'da min Fader har ført Krig for eders Skyld, og han har sat sig i Livsfare og friet eder af Midianiternes Haand;',
        18: 'og I dog ere staaede op imod min Faders Hus i Dag og have ihjelslaget hans Sønner, halvfjerdsindstyve Mænd, paa een Sten, og have gjort Abimelek, hans Tjenestekvindes Søn, til Konge over Mændene i Sikem, fordi han er eders Broder;',
        19: 'ja, dersom I have handlet troligt og redeligt imod Jerub-Baal og imod hans Hus paa denne Dag: Da værer glade over Abimelek, og han være ogsaa glad over eder;',
        20: 'men hvis ikke, da udkomme Ild fra Abimelek og fortære Mændene i Sikem og Millo Hus; der udkomme og Ild fra Mændene i Sikem og af Millo Hus og fortære Abimelek!',
        21: 'Og Jotham flyede og undveg og gik til Beer, og han boede der borte fra sin Broder, Abimeleks Ansigt.',
        22: 'Og Abimelek var Fyrste over Israel tre Aar.',
        23: 'Og Gud sendte en ond Aand imellem Abimelek og imellem Mændene i Sikem, og Mændene i Sikem bleve utro mod Abimelek,',
        24: 'for at den Vold mod de halvfjerdsindstyve Jerub-Baals Sønner skulde komme, og deres Blod skulde lægges paa Abimelek, deres Broder, som havde ihjelslaget dem, og paa Mændene i Sikem, som havde styrket hans Hænder til at ihjelslaa sine Brødre.',
        25: 'Og Mændene i Sikem lagde et Baghold for ham paa Bjergenes Toppe, og de røvede fra hver, der gik forbi dem paa Vejen; og det blev Abimelek tilkendegivet.',
        26: 'Men Gaal, Ebeds Søn og hans Brødre kom, og de gik over til Sikem; og Mændene i Sikem forlode sig paa ham.',
        27: 'Og de gik ud paa Marken og høstede deres Vingaarde og traadte Vindruerne og gjorde sig Forlystelser, og de gik ind i deres Guders Huse og aade og drak og bandede Abimelek.',
        28: 'Og Gaal, Ebeds Søn, sagde: Hvo er Abimelek og hvo er Sikem, at vi skulle tjene ham? er han ikke Jerub-Baals Søn, og Sebul hans Befalingsmand? tjener I Hemors, Sikems Faders, Folk! men vi, hvorfor skulle vi tjene ham?',
        29: 'Og hvo vil give dette Folk under min Haand, saa vil jeg bortskaffe Abimelek; men han sagde til Abimelek: Formér din Hær og drag ud!',
        30: 'Der Sebul, den Øverste i Staden, hørte Gaals, Ebeds Søns, Ord, da optændtes hans Vrede.',
        31: 'Og han sendte i Smug Bud til Abimelek og lod sige: Se, Gaal, Ebeds Søn, og hans Brødre ere komne til Sikem, og se, de opægge Staden imod dig.',
        32: 'Saa gør dig nu rede om Natten, du og Folket, som er hos dig, og lur paa Marken!',
        33: 'Og det skal ske, om Morgenen, naar Solen gaar op, da staa aarle op og overfald Staden; og se, naar han og det Folk, som er hos ham, drage ud imod dig, da maa du gøre med ham, som din Haand magter.',
        34: 'Og Abimelek stod op om Natten og alt det Folk, som var hos ham, og de lurede paa Sikem med fire Hobe.',
        35: 'Og Gaal, Ebeds Søn, gik ud og stod ved Indgangen af Stadsporten; men Abimelek stod op og det Folk, som var med ham, af Bagholdet.',
        36: 'Og der Gaal saa Folket, da sagde han til Sebul: Se, der kommer Folk ned fra Bjergenes Toppe; da sagde Sebul til ham: Du anser Skyggen af Bjergene for Folk.',
        37: 'Og Gaal blev ydermere ved at tale og sagde: Se, der kommer Folk ned fra Landets Højder, og een Hob kommer fra Vejen til Troldmændenes Eg.',
        38: 'Da sagde Sebul til ham: Hvor er nu din Mund, du som sagde: Hvo er Abimelek, at vi skulle tjene ham? er dette ikke det Folk, som du foragtede? Kære, gak du nu ud og strid imod det!',
        39: 'Og Gaal gik ud, frem for Mændene i Sikem, og stred imod Abimelek.',
        40: 'Men Abimelek forfulgte ham, og han flyede for hans Ansigt; og der faldt mange ihjelslagne indtil Indgangen til Porten.',
        41: 'Og Abimelek blev i Aruma; men Sebul uddrev Gaal og hans Brødre, saa at de ikke maatte blive i Sikem.',
        42: 'Og det skete den anden Dag, da gik Folket ud paa Marken, og de gave Abimelek det til Kende.',
        43: 'Da tog han Folket og delte dem i tre Hobe og lagde et Baghold paa Marken; og han saa, og se, Folket gik ud af Staden, og han rejste sig imod dem og slog dem.',
        44: 'Og Abimelek og de Hobe, som vare hos ham, overfaldt dem og stillede sig for Indgangen til Stadens Port, og to Hobe overfaldt alle dem, som vare paa Marken, og sloge dem.',
        45: 'Da stred Abimelek imod Staden den ganske Dag og indtog Staden og ihjelslog Folket, som var der udi; og han nedbrød Staden og besaaede den med Salt.',
        46: 'Der alle Mændene i Taarnet i Sikem hørte det, da gik de ind i Beriths Gudshuses Taarn.',
        47: 'Og det kundgjordes Abimelek, at alle Mændene paa Taarnet i Sikem havde samlet sig.',
        48: 'Da gik Abimelek op paa Bjerget Zalmon, han og alt Folket, som var med ham, og Abimelek tog Øksen i sin Haand og huggede en Gren af Træerne og løftede den op og lagde den paa sin Skulder; og han sagde til Folket, som var med ham: Hvad I saa, jeg gjorde, skynder eder at gøre som jeg!',
        49: 'Da huggede ogsaa alt Folket hver sin Gren af, og de gik efter Abimelek og lagde dem op til Taarnet og satte med dem Ild paa Taarnet, saa at ogsaa alle Mænd paa Taarnet i Sikem døde, ved Tusinde Mænd og Kvinder.',
        50: 'Saa drog Abimelek til Thebez; og han lejrede sig mod Thebez og indtog den.',
        51: 'Men der var et stærkt Taarn midt i Staden, derhen flyede alle Mændene og Kvinderne, ja alle Borgerne i Staden og lukkede til efter sig; og de stege op paa Taget af Taarnet.',
        52: 'Da kom Abimelek til Taarnet og stred derimod; og han kom nær til Døren paa Taarnet forat opbrænde det med Ild.',
        53: 'Men en Kvinde kastede et Stykke af en Møllesten paa Abimeleks Hoved og knuste hans Hovedpande.',
        54: 'Da raabte han hasteligen ad den unge Karl, som bar hans Vaaben, og sagde til ham: Drag dit Sværd ud og slaa mig ihjel, at de ikke skulle sige om mig: En Kvinde slog ham ihjel; og hans unge Karl stak ham igennem, og han døde.',
        55: 'Og de israelitiske Mænd saa, at Abimelek var død, da gik de hver til sit Sted.',
        56: 'Saa betalte Gud Abimelek det onde, som han havde gjort imod sin Fader, der han ihjelslog sine halvfjerdsindstyve Brødre.',
        57: 'Og al Sikems Mænds Ondskab lod Gud komme tilbage paa deres Hoved; og Jothams, Jerub-Baals Søns, Forbandelse kom over dem.',
    },
    10: {
        1: 'Og efter Abimelek opstod Thola, en Søn af Pua, Dodos Søn, en Mand af Isaskar, at frelse Israel; og han boede i Samir paa Efraims Bjerg.',
        2: 'Og han dømte Israel tre og tyve Aar, og han døde og blev begraven i Samir.',
        3: 'Og efter ham opstod Gileaditeren Jair og dømte Israel to og tyve Aar.',
        4: 'Og han havde tredive Sønner, som rede paa tredive Asenfoler, og de havde tredive Stæder; dem kaldte de Jairs Byer indtil denne Dag, de ligge i Gileads Land.',
        5: 'Og Jair døde og blev begraven i Kamon.',
        6: 'Og Israels Børn bleve ved at gøre ondt for Herrens Øjne og tjente Baalerne og Astarterne og Syriens Guder og Zidons Guder og Moabs Guder og Ammons Børns Guder og Filisternes Guder; og de forlode Herren og tjente ham ikke.',
        7: 'Da optændtes Herrens Vrede imod Israel, og han solgte dem i Filisternes Haand og Ammons Børns Haand.',
        8: 'Og de nedsloge og knuste Israels Børn i det samme Aar; atten Aar plagede de alle Israels Børn, som vare paa hin Side Jordanen i Amoriternes Land, som er i Gilead.',
        9: 'Og Ammons Børn droge over Jordanen at stride endog imod Juda og imod Benjamin og imod Efraims Hus, saa at Israel var saare trængt.',
        10: 'Da raabte Israels Børn til Herren og sagde: Vi have syndet imod dig, fordi vi have forladt vor Gud og tjent Baalerne.',
        11: 'Og Herren sagde til Israels Børn: Havde ikke Ægypter og Amoriter, Ammons Børn og Filister',
        12: 'og Zidonier og Amalek og Maon undertrykket eder? og I raabte til mig, og jeg frelste eder af deres Haand.',
        13: 'Og I forlode mig og tjente andre Guder; derfor vil jeg ikke blive ved at frelse eder.',
        14: 'Gaar og raaber til de Guder, som I have udvalgt; lad dem frelse eder i eders Trængsels Tid.',
        15: 'Da sagde Israels Børn til Herren: Vi have syndet; gør du med os efter alt det, som er godt for dine Øjne; dog, kære, udfri os paa denne Dag.',
        16: 'Og de kastede de fremmedes Guder bort fra sig og tjente Herren; og han ynkedes inderlig over Israels Nød.',
        17: 'Og Ammons Børn bleve sammenkaldte, og de lejrede sig i Gilead; men Israels Børn samledes og lejrede sig i Mizpa.',
        18: 'Og Folket, Fyrsterne i Gilead, sagde den ene til den anden: Hvo er den Mand, som vil begynde at stride imod Ammons Børn? han skal være Hoved for alle dem, som bo i Gilead.',
    },
    11: {
        1: 'Og Gileaditeren Jeftha var vældig til Strid, men han var en Horekvindes Søn; og Gilead havde avlet Jeftha.',
        2: 'Og Gileads Hustru fødte ham Børn; da Hustruens Børn bleve store, udstødte de Jeftha og sagde til ham: Du skal ikke arve i vor Faders Hus, thi du er en anden Kvindes Søn.',
        3: 'Da flyede Jeftha fra sine Brødres Ansigt og boede i Landet Tob; og der samlede sig til Jeftha løse Mænd, og de droge ud med ham.',
        4: 'Og det skete efter nogle Aar, da strede Ammons Børn imod Israel.',
        5: 'Og det skete, der Ammons Børn strede mod Israel, da gik de Ældste af Gilead hen at hente Jeftha fra Landet Tob.',
        6: 'Og de sagde til Jeftha: Kom, saa skal du være vor Øverste, og vi ville stride imod Ammons Børn.',
        7: 'Og Jeftha sagde til de Ældste af Gilead: Have I ikke hadet mig og udstødt mig af min Faders Hus? hvorfor komme I nu til mig, efterdi I have Trængsel?',
        8: 'Og de Ældste af Gilead sagde til Jeftha: Derfor vende vi nu tilbage til dig, at du skal gaa med os og stride imod Ammons Børn; og du skal være vort Hoved, ja alle deres, som bo i Gilead.',
        9: 'Og Jeftha sagde til de Ældste af Gilead: Dersom I hente mig for at stride imod Ammons Børn, og Herren giver dem for mit Ansigt, skal jeg da være eders Hoved?',
        10: 'Da sagde de Ældste af Gilead til Jeftha: Herren skal være Vidne imellem os, dersom vi ikke gøre saaledes efter dine Ord.',
        11: 'Saa gik Jeftha med de Ældste af Gilead, og Folket satte ham over sig til et Hoved og til en Øverste, og Jeftha talede alle sine Ord for Herrens Ansigt i Mizpa.',
        12: 'Da sendte Jeftha Bud til Ammons Børns Konge og lod sige: Hvad har jeg med dig at gøre, at du kommer til mig at stride imod mit Land?',
        13: 'Ammons Børns Konge sagde til Jefthas Bud: Fordi Israel har taget mit Land, der han drog op af Ægypten, fra Arnon og indtil Jakob og indtil Jordanen; saa giv mig nu de Stæder tilbage med Fred!',
        14: 'Men Jeftha sendte atter Bud til Ammons Børns Konge.',
        15: 'Og han lod sige til ham: Saa siger Jeftha: Israel har ikke taget Moabs Land eller Ammons Børns Land;',
        16: 'thi der de droge op af Ægypten, da vandrede Israel i Ørken indtil det røde Hav, og kom til Kades.',
        17: 'Og Israel sendte Bud til Edomiternes Konge og lod sige: Kære, lad mig drage igennem dit Land, men Edomiternes Konge vilde ikke høre; han sendte ogsaa Bud til Moabiternes Konge, men denne vilde heller ikke; saa blev Israel i Kades.',
        18: 'Derefter vandrede han i Ørken og drog omkring Edomiternes Land og Moabiternes Land og kom fra Solens Opgang til Moabiternes Land, og de lejrede sig paa hin Side Arnon; og de kom ikke i Moabiternes Landemærke; thi Arnon er Moabiternes Landemærke.',
        19: 'Og Israel sendte Bud til Sihon, Amoriternes Konge, Kongen i Hesbon, og Israel lod ham sige: Kære, lad os drage igennem dit Land indtil mit Sted.',
        20: 'Men Sihon troede ikke Israel, saa at han lod ham drage igennem sit Landemærke; men Sihon samlede alt sit Folk, og de lejrede sig i Jahza, og han stred imod Israel.',
        21: 'Da gav Herren, Israels Gud, Sihon og alt hans Folk i Israels Haand, og de sloge dem; saa indtog Israel til Ejendom hele Landet fra Amoriterne, som boede sammesteds.',
        22: 'Og de indtoge alt Amoriternes Landemærke til Ejendom, fra Arnon og indtil Jabok og fra Ørken og indtil Jordanen.',
        23: 'Saa har nu Herren, Israels Gud, fordrevet Amoriterne fra sit Folks Israels Ansigt; og du vil tage det i Eje?',
        24: 'Mon du ikke tager til Eje det, som din Gud Kamos giver dig i Eje? og alt hvad Herren vor Gud har gjort ryddeligt for vort Ansigt, det tage vi i Eje.',
        25: 'Og nu, er du vel meget bedre end Balak, Zippors Søn, Moabiternes Konge? har han vel trættet med Israel, eller har han vel ført Krig imod dem?',
        26: 'Da Israel har boet i Hesbon og i dens tilhørende Stæder og i Aroer og i dens tilhørende Stæder og i alle Stæderne, som ligge ved Arnons Bredder, tre Hundrede Aar, hvorfor friede I dem da ikke i den Tid?',
        27: 'Og jeg har intet syndet imod dig, og du gør dette onde imod mig, at du strider imod mig; Herren, som er Dommer, skal dømme i Dag imellem Israels Børn og imellem Ammons Børn.',
        28: 'Men Ammons Børns Konge hørte ikke Jefthas Ord, hvilke han sendte til ham.',
        29: 'Og Herrens Aand var over Jeftha, og han drog igennem Gilead og Manasse; og han drog over til Mizpa i Gilead, og fra Mizpa i Gilead drog han over til Ammons Børn,',
        30: 'og Jeftha lovede Herren et Løfte og sagde: Dersom du giver Ammons Børn i min Haand,',
        31: 'da skal det ske, at det, som gaar ud, ja det, som gaar ud af mit Huses Døre imod mig, naar jeg kommer tilbage med Fred fra Ammons Børn, det skal høre Herren til, og jeg vil ofre det til et Brændoffer.',
        32: 'Saa drog Jeftha over til Ammons Børn for at stride imod dem, og Herren gav dem i hans Haand.',
        33: 'Og han slog dem fra Aroer, og indtil man kommer til Minnith, tyve Stæder, og indtil Abel-Keramim med et saare stort Slag; saa bleve Ammons Børn ydmygede for Israels Børns Ansigt.',
        34: 'Og Jeftha kom til Mizpa til sit Hus, og se, hans Datter gik ud mod ham med Trommer og med Dans, og hun var hans eneste; han havde ellers hverken Søn eller Datter.',
        35: 'Og det skete, der han saa hende, da sønderrev han sine Klæder og sagde: Ak, min Datter! du har nedbøjet mig saare, og du har bedrøvet mig inderligen; thi jeg oplod min Mund til Herren, og jeg kan ikke kalde det tilbage.',
        36: 'Og hun sagde til ham: Min Fader! har du opladt din Mund til Herren, da gør med mig, som det er udgaaet af din Mund, efter at Herren har skaffet dig fuldkommen Hævn over dine Fjender, over Ammons Børn.',
        37: 'Og hun sagde til sin Fader: Denne Ting lad mig vederfares, giv mig Frist to Maaneder, at jeg maa gaa og fare ned paa Bjergene og begræde min Jomfrustand, jeg og mine Veninder.',
        38: 'Og han sagde: Gak hen, og han gav hende Frist to Maaneder; da gik hun med sine Veninder hen og begræd sin Jomfrustand, paa Bjergene.',
        39: 'Og det skete, der to Maaneder vare til Ende, da kom hun tilbage til sin Fader, og han gjorde med hende efter sit Løfte, som han havde lovet; og hun kendte ikke Mand. Og det blev en Skik i Israel:',
        40: 'Israels Døtre gaa fra Aar til Aar for at prise Gileaditeren Jefthas Datter fire Dage om Aaret.',
    },
    12: {
        1: 'Og hver Mand af Efraim blev opbudt og drog over mod Norden, og de sagde til Jeftha: Hvorfor gik du over til at stride imod Ammons Børn og kaldte os ikke at gaa med dig? Vi ville brænde dit Hus over dig med Ild.',
        2: 'Og Jeftha sagde til dem: Jeg og mit Folk havde en svar Trætte med Ammons Børn; og jeg kaldte ad eder, men I frelste mig ikke af deres Haand.',
        3: 'Der jeg saa, at du ikke vilde frelse, da satte jeg mit Liv i min Haand og drog over til Ammons Børn; og Herren gav dem i min Haand; og hvorfor komme I op til mig paa denne Dag at stride imod mig?',
        4: 'Og Jeftha samlede alle Mænd i Gilead og stred imod Efraim; og Mændene i Gilead sloge Efraim; thi de havde sagt: I Mænd af det Gilead, som ligger imellem Efraim og Manasse, ere Overløbere fra Efraim.',
        5: 'Thi Gileaditerne indtoge Jordanens Færgestæder overfor Efraim, og det skete, naar nogen af de undkomne af Efraim sagde: Jeg vil gaa over, da sagde Mændene af Gilead til ham: Er du en Efratiter? og han sagde: Nej.',
        6: 'Da sagde de til ham: Kære, sig: Sjibboleth, og han sagde: Sibboleth, og kunde saaledes ikke udtale det ret; saa grebe de ham og sloge ham ihjel ved Jordanens Færgestæder, og der faldt paa den samme Tid af Etraim to og fyrretyve Tusinde.',
        7: 'Og Jeftha dømte Israel seks Aar; og Gileaditeren Jeftha døde og blev begraven i en af Stæderne udi Gilead.',
        8: 'Og efter ham dømte Ibzan af Bethlehem Israel.',
        9: 'Og han havde tredive Sønner, og tredive Døtre udstyrede han og indførte tredive Døtre til sine Sønner udenfra; og han dømte Israel syv Aar.',
        10: 'Og Ibzan døde og blev begraven i Bethlehem.',
        11: 'Og efter ham dømte Sebuloniteren Elon Israel; og han dømte Israel ti Aar.',
        12: 'Og Sebuloniteren Elon døde, og han blev begraven i Ajalon udi Sebulons Land.',
        13: 'Og efter ham dømte Pireathoniteren Abdon, Hillels Søn, Israel.',
        14: 'Og han havde fyrretyve Sønner og tredive Sønnesønner, som rede paa halvfjerdsindstyve Asenfoler; og han dømte Israel otte Aar.',
        15: 'Og Abdon, Pireathoniteren Hillels Søn døde; og han blev begraven i Pireathon udi Efraims Land paa Amalekiternes Bjerg.',
    },
    13: {
        1: 'Og Israels Børn bleve ved at gøre det, som var ondt for Herrens Øjne, og Herren gav dem i Filisternes Haand fyrretyve Aar.',
        2: 'Og der var en Mand fra Zora, af en Daniters Slægt, og hans Navn var Manoa; og hans Hustru var ufrugtbar og fødte ikke.',
        3: 'Og Herrens Engel aabenbaredes for Kvinden, og han sagde til hende: Se, kære, du er ufrugtbar og føder ikke, men du skal blive frugtsommelig og føde en Søn.',
        4: 'Saa, kære, forvar dig nu, at du ikke drikker Vin ej heller stærk Drik, og at du ikke æder noget urent.',
        5: 'Thi se, du skal vorde frugtsommelig og føde en Søn, og paa hans Hoved skal ikke komme Bagekniv; thi Drengen skal være en Guds Nasiræer fra Moders Liv af, og han skal begynde at frelse Israel af Filisternes Haand.',
        6: 'Da kom Kvinden og sagde til sin Mand: Der kom en Guds Mand til mig, og hans Udseende var som en Guds Engels Udseende, saare forfærdelig; og jeg spurgte ham ikke, hvorfra han var, og han kundgjorde mig ikke sit Navn.',
        7: 'Men han sagde til mig: Se, du skal vorde frugtsommelig og føde en Søn; saa skal du nu ikke drikke Vin eller stærk Drik og ikke æde noget urent; thi Drengen skal være en Guds Nasiræer fra Moders Liv af indtil sin Dødsdag.',
        8: 'Da bad Manoa til Herren og sagde: Hør mig, Herre! Kære, lad den Guds Mand, som du udsendte, atter komme til os, at han kan lære os, hvad vi skulle gøre ved Drengen, som skal fødes.',
        9: 'Og Gud hørte Manoas Bøst; og Guds Engel kom atter til Kvinden, og hun sad paa Marken; men hendes Mand Manoa var ikke hos hende.',
        10: 'Da hastede Kvinden og løb og gav sin Mand det til Kende, og hun sagde til ham: Se, den Mand, der kom til mig hin Dag, aabenbaredes for mig.',
        11: 'Da stod Manoa op og gik efter sin Hustru, og han kom til Manden og sagde til ham: Er du den Mand, som talede med Kvinden? og han sagde: Ja, jeg er.',
        12: 'Og Manoa sagde: Naar det nu kommer, som du har sagt, hvad skulle vi iagttage med Drengen, og hvad skulle vi gøre ved ham?',
        13: 'Og Herrens Engel sagde til Manoa: For alt det, som jeg har sagt til Kvinden, skal hun tage sig i Vare.',
        14: 'Hun skal ikke æde af noget, som kommer af Vinstokken, og ikke drikke Vin eller stærk Drik og intet urent æde; alt det, som jeg har budet hende, skal hun holde.',
        15: 'Og Manoa sagde til Herrens Engel: Kære, lad os opholde dig lidt, saa ville vi lave et Bukkekid for dit Ansigt.',
        16: 'Men Herrens Engel sagde til Manoa: Dersom du opholder mig, æder jeg dog ikke af din Mad, men dersom du vil gøre dit Brændoffer, maa du ofre Herren det; thi Manoa vidste ikke, at det var Herrens Engel.',
        17: 'Og Manoa sagde til Herrens Engel: Hvad er dit Navn, at vi kunne ære dig, naar det kommer, som du har sagt.',
        18: 'Og Herrens Engel sagde til ham: Hvi spørger du om mit Navn? se, det er underligt.',
        19: 'Da tog Manoa et Bukkekid og Madofret og ofrede det for Herren paa Klippen; og Engelen gjorde et Under, men Manoa og hans Hustru saa til.',
        20: 'Og det skete, der Luen for op fra Alteret til Himmelen, da for Herrens Engel op i Luen fra Alteret; der Manoa og hans Hustru saa det, da faldt de paa deres Ansigt til Jorden.',
        21: 'Og Herrens Engel lod sig ikke ydermere se for Manoa og for hans Hustru; da fornam Manoa, at det var Herrens Engel.',
        22: 'Og Manoa sagde til sin Hustru: Vi dø visseligen; thi vi have set Gud.',
        23: 'Men hans Hustru sagde til ham: Om Herren havde haft Lyst til at ihjelslaa os, havde han ikke taget Brændoffer og Madoffer af vor Haand, ej heller ladet os se alt dette og paa denne Tid ej ladet os høre saadanne Ting.',
        24: 'Og Kvinden fødte en Søn og kaldte hans Navn Samson; og Drengen blev stor, og Herren velsignede ham.',
        25: 'Og Herrens Aand begyndte at drive ham i Dans Lejr imellem Zora og Esthaol.',
    },
    14: {
        1: 'Og Samson gik ned til Thimna og saa en Kvinde af Filisternes Døtre i Thimna.',
        2: 'Og han kom op og gav sin Fader og sin Moder det til Kende og sagde: Jeg har set en Kvinde af Filisternes Døtre i Thimna; saa tager mig nu hende til Hustru.',
        3: 'Og hans Fader og hans Moder sagde til ham: Er der ingen Kvinde iblandt dine Brødres Døtre og iblandt alt mit Folk, at du gaar hen at tage en Hustru af de uomskaarne Filister? Og Samson sagde til sin Fader: Tag mig denne, thi hun er den rette for mine Øjne.',
        4: 'Men hans Fader og hans Moder vidste ikke, at det var af Herren, thi han søgte en Anledning fra Filisterne selv; men Filisterne herskede paa den Tid over Israel.',
        5: 'Saa gik Samson og hans Fader og hans Moder ned til Thimna; og de kom til Thimnas Vingaarde, og se, da kom en ung Løve brølende imod ham.',
        6: 'Og Herrens Aand kom heftig over ham, og han sled den i Stykker, som man slider et Kid, og han havde ikke noget i sin Haand; og han gav ikke sin Fader eller sin Moder til Kende, hvad han havde gjort.',
        7: 'Og han kom ned og talede med Kvinden, og hun var den rette for Samsons Øjne.',
        8: 'Og nogen Tid derefter kom han tilbage for at tage hende, og han bøjede af fra Vejen for at bese Løvens Aadsel; og se, der var en Bisværm og Honning i Løvens Krop.',
        9: 'Og han tog den i sine Hænder, og medens han gik videre, aad han og gik saa til sin Fader og til sin Moder og gav dem, og de aade, men han gav dem ikke til Kende, at han havde taget Honningen af Løvens Krop.',
        10: 'Og der hans Fader kom ned til Kvinden, da gjorde Samson der et Gæstebud; thi saaledes plejede de unge Karle at gøre.',
        11: 'Og det skete, der de saa ham, da toge de tredive Selskabsbrødre, og de vare hos ham.',
        12: 'Da sagde Samson til dem: Kære, jeg vil fremsætte for eder en mørk Tale; dersom I forklare mig den i disse syv Gæstebuds Dage og finde derpaa, da vil jeg give eder tredive Skjorter og tredive Klædninger til at skifte med.',
        13: 'Men kunne I ikke forklare mig den, da skulle I give mig tredive Skjorter og tredive Klædninger til at skifte med; og de sagde til ham: Fremsæt din mørke Tale og lad os høre den!',
        14: 'Og han sagde til dem: Der udgik Mad af Æderen, og der udgik Sødme af den stærke; og de kunde ikke forklare den mørke Tale i tre Dage.',
        15: 'Og det skete paa den syvende Dag, da sagde de til Samsons Hustru: Lok din Mand til, at han forklarer os den mørke Tale, at vi ikke skulle brænde dig og din Faders Hus med Ild; have I indbudet os, at I ville gøre os fattige eller ikke?',
        16: 'Da græd Samsons Hustru over ham og sagde: Du hader mig ikkun og har mig ikke kær, du har fremsat en mørk Tale for mit Folks Børn og ikke forklaret den for mig; og han sagde til hende: Se, jeg har ikke forklaret den for min Fader eller for min Moder, og skulde jeg forklare den for dig?',
        17: 'Og hun græd over ham i de syv Dage, som de havde Gæstebud; og det skete, paa den syvende Dag forklarede han den for hende, thi hun trængte ham, og hun forklarede den mørke Tale for sit Folks Børn.',
        18: 'Da sagde Mændene af Staden til ham paa den syvende Dag, før Solen gik ned: Hvad er sødere end Honning? og hvad er stærkere end en Løve? Da sagde han til dem: Dersom I ikke havde pløjet med min Kalv, da havde I ikke fundet paa min mørke Tale.',
        19: 'Og Herrens Aand kom heftig over ham, og han gik ned til Askalon og slog tredive Mænd af dem og tog deres Klæder og gav Klædninger til at skifte med til dem, som forklarede den mørke Tale; og hans Vrede optændtes, og han gik op til sin Faders Hus.',
        20: 'Men Samsons Hustru blev given hans Selskabsbroder, som havde været i Selskab med ham.',
    },
    15: {
        1: 'Og det skete nogen Tid derefter, udi Hvedehøstens Dage, at Samson besøgte sin Hustru med et Gedekid, og han sagde: Jeg vil gaa til min Hustru ind i Kammeret, og hendes Fader tilstedte ham ikke at komme ind.',
        2: 'Og hendes Fader sagde: Jeg tænkte, at du havde faaet Had til hende, og jeg gav din Selskabsbroder hende; er ikke hendes yngre Søster bedre end hun? Kære, lad hende være din i Stedet for denne.',
        3: 'Da sagde Samson til dem: Jeg er denne Gang uden Skyld for Filisterne, naar jeg gør ondt imod dem.',
        4: 'Og Samson gik hen og greb tre Hundrede Bæve, og han tog Blus og vendte Stjært til Stjært og satte et Blus midt imellem to Stjærte.',
        5: 'Og han tændte Ild i Blussene og lod dem fare ind iblandt Filisternes staaende Korn, og han satte Ild baade paa Negene og paa det staaende Korn og paa Olivenhaverne.',
        6: 'Da sagde Filisterne: Hvo har gjort dette? og de sagde: Samson, den Thimniters Svigersøn, fordi han tog hans Hustru og gav hans Selskabsbroder hende; da droge Filisterne op og opbrændte hende og hendes Fader med Ild.',
        7: 'Men Samson sagde til dem: Naar I gøre saaledes, da vil jeg ikke holde op, førend jeg faar hævnet mig paa eder.',
        8: 'Og han slog dem med et stort Slag paa Hoften og paa Laarene; og han gik ned og boede i en Hule i Klippen Etham.',
        9: 'Da droge Filisterne op og lejrede sig imod Juda og adspredte sig i Leki.',
        10: 'Og Judas Mænd sagde: Hvi ere I dragne op imod os? og de sagde: Vi ere komne op for at binde Samson, for at gøre ved ham, ligesom han har gjort ved os.',
        11: 'Da droge tre Tusinde Mænd af Juda ned til Hulen i Klippen Etham, og de sagde til Samson: Ved du ikke, at Filisterne herske over os, og hvorfor har du gjort dette imod os? og han sagde til dem: Ligesom de gjorde ved mig, saa har jeg gjort ved dem.',
        12: 'Og de sagde til ham: Vi ere komne ned for at binde dig, for at give dig i Filisternes Haand, og Samson sagde til dem: Sværger mig, at I ikke ville anfalde mig.',
        13: 'Og de sagde til ham: Nej, men vi ville kun binde dig og give dig i deres Haand, men ikke slaa dig ihjel; og de bandt ham med to nye Reb, og de førte ham op fra Klippen.',
        14: 'Der han kom til Leki, da skrege Filisterne mod ham; men Herrens Aand kom heftig over ham, og de Reb, som vare om hans Arme, bleve som Traade, brændte af Ilden, og hans Baand smuldrede og faldt af hans Hænder.',
        15: 'Og han fandt en frisk Asenkæft, og han udrakte sin Haand og tog den og slog dermed tusinde Mand.',
        16: 'Og Samson sagde: Med en Asenkæft har jeg slaget en Hob, ja to Hobe, med en Asenkæft har jeg slaget tusinde Mand.',
        17: 'Og det skete, der han havde fuldendt at tale, da kastede han Kæften af sin Haand; og han kaldte det samme Sted Ramath-Leki.',
        18: 'Men han tørstede saare, og han kaldte paa Herren og sagde: Du har givet denne store Frelse ved din Tjeners Haand; men nu maa jeg dø af Tørst og falde udi de uomskaarnes Haand.',
        19: 'Da flakte Gud Kindtanden, som var i Kæften, og der udgik Vand af den, og han drak, og hans Aand kom igen, og han blev ved Live; derfor kaldte man dens Navn En-Hakore Asker-Baleki indtil paa denne Dag.',
        20: 'Og han dømte Israel i Filisternes Dage, tyve Aar.',
    },
    16: {
        1: 'Og Samson gik til Gaza, og han saa der en Kvinde, en Skøge, og kom til hende.',
        2: 'Og man sagde til Gaziterne: Samson er kommen hid, og de gik omkring og lurede paa ham den ganske Nat ved Stadsporten; men de vare stille den ganske Nat, og de sagde: Naar det bliver lyst i Morgen, da ville vi slaa ham ihjel.',
        3: 'Og Samson laa indtil Midnatten, og han stod op om Midnat og tog fat paa Dørene af Stadens Port og paa begge Stolperne og løftede dem op tillige med Slaaerne og lagde dem paa sine Skuldre, og han bar dem op paa Toppen af det Bjerg, som er lige for Hebron.',
        4: 'Og det skete derefter, at han fik Kærlighed til en Kvinde ved Bækken Sorek, og hendes Navn var Dalila.',
        5: 'Og Filisternes Fyrster kom op til hende og sagde til hende: Lok ham, og se, hvorudi hans store Kraft bestaar, og hvormed vi formaa noget imod ham, saa ville vi binde ham for at plage ham; og vi ville hver give dig tusinde og hundrede Sekel Sølv.',
        6: 'Og Dalila sagde til Samson: Kære, giv mig til Kende, hvorudi din store Kraft bestaar, og hvormed du kan bindes, at man kan plage dig.',
        7: 'Og Samson sagde til hende: Dersom de bandt mig med syv grønne Bast, som ikke ere blevne tørre, da blev jeg svag og blev som et andet Menneske.',
        8: 'Da bragte Filisternes Fyrster hende syv grønne Bast, som ikke vare tørre; og hun bandt ham med dem.',
        9: 'Og hun havde een, som lurede, siddende i Kammeret; og hun sagde til ham: Filisterne ere over dig, Samson! men han sønderrev Bastene, som en Traad af Blaar sønderrives, naar den berøres af Ilden, og man fik ej at vide, hvori hans Kraft bestod.',
        10: 'Da sagde Dalila til Samson: Se, du har bedraget mig og sagt Løgn for mig; kære, giv mig nu til Kende, hvormed du kan bindes.',
        11: 'Og han sagde til hende: Dersom de bandt mig fast med nye Beb, med hvilken ingen Gerning er gjort, da blev jeg svag og blev som et andet Menneske.',
        12: 'Da tog Dalila nye Beb og bandt ham med dem, og hun sagde til ham: Filisterne ere over dig, Samson! men hun havde een, som lurede, siddende i Kammeret; og han rev dem af sine Arme som en Traad.',
        13: 'Og Dalila sagde til Samson: Hidindtil har du bedraget mig og sagt Løgn for mig, giv mig dog til Kende, hvormed du kan bindes? og han sagde til hende: Dersom du vævede mine syv Hovedlokker om Væverstangen.',
        14: 'Og hun fæstede dem til med en Nagle, og hun sagde til ham: Filisterne ere over dig, Samson! men han vaagnede op af sin Søvn og rykkede Vævernaglen op tillige med Væverstangen.',
        15: 'Og hun sagde til ham: Hvorledes kan du sige: Jeg elsker dig, da dit Hjerte ikke er med mig? nu har du tre Gange bedraget mig og ikke givet mig til Kende, hvori din store Kraft bestaar.',
        16: 'Men det skete, der hun trængte ham alle Dage med sine Ord og plagede ham meget, da blev hans Sjæl bekymret indtil Døden.',
        17: 'Og han gav hende sit ganske Hjerte til Kende og sagde til hende: Der kom ikke Bagekniv paa mit Hoved, thi jeg er en Guds Nasiræer fra Moders Liv af; dersom jeg rages, da viger min Kraft fra mig, og jeg bliver svag og bliver som alle andre Mennesker.',
        18: 'Der Dalila saa, at han havde givet hende sit ganske Hjerte til Kende, da sendte hun hen og lod kalde Filisternes Fyrster og sige: Kommer denne Gang op, thi han har givet mig sit ganske Hjerte til Kende; da kom Filisternes Fyrster op til hende og bragte Sølvet op i deres Haand.',
        19: 'Og hun lod ham sove paa sine Knæ og kaldte ad en Mand og lod hans syv Hovedlokker afrage; og hun begyndte at plage ham; da var hans Kraft vegen fra ham.',
        20: 'Og hun sagde: Filisterne ere over dig, Samson! og han vaagnede op af sin Søvn og sagde: Jeg vil gaa ud, som jeg mange Gange har gjort, og slide mig løs; men han vidste ikke, at Herren var vegen fra ham.',
        21: 'Men Filisterne grebe ham og stak hans Øjne ud; og de førte ham ned til Gaza og bandt ham med to Kobberlænker, og han malede i Fangernes Hus.',
        22: 'Og hans Hovedhaar begyndte at gro, hvor han var raget.',
        23: 'Men Filisternes Fyrster samledes, for at ofre til deres Gud, Dagon, et stort Offer og for at være glade; thi de sagde: Vor Gud har givet vor Fjende Samson i vor Haand.',
        24: 'Og der Folket saa ham, da lovede de deres Gud; thi de sagde: Vor Gud har givet vor Fjende i vor Haand, og den, som ødelagde vort Land og slog mange af vore ihjel.',
        25: 'Og det skete, der deres Hjerter vare vel til Mode, da sagde de: Kalder ad Samson og lader ham lege for os; da kaldte de Samson ud af Fangernes Hus, og han legede for deres Aasyn, og de stillede ham imellem Pillerne.',
        26: 'Men Samson sagde til den unge Karl, som holdt ham ved hans Haand: Lad mig hvile og lad mig føle paa de Piller, som bære Huset, at jeg kan hælde mig op til dem.',
        27: 'Og Huset var fuldt af Mænd og Kvinder, der var og alle Filisternes Fyrster, og paa Taget vare ved tre Tusinde Mænd og Kvinder, som saa til, da Samson legede.',
        28: 'Men Samson kaldte paa Herren og sagde: Herre, Herre! Kære, kom mig i Hu! og styrk mig dog, Gud! denne Gang, at jeg maa een Gang hævne mig til Gavns paa Filisterne for begge mine Øjnes Skyld.',
        29: 'Og Samson greb omkring de to midterste Piller, som bare Huset, og han støttede sig mod dem, den ene var i hans højre og den anden i hans venstre Haand.',
        30: 'Og Samson sagde: Min Sjæl dø med Filisterne! og han bøjede sig med Kraft: Da faldt Huset paa Fyrsterne og paa alt Folket, som vare derudi, og de døde vare flere, som han dræbte ved sin Død, end han dræbte i sit Liv.',
        31: 'Da kom hans Brødre og hans Faders ganske Hus ned, og de toge ham op, og de droge op og begravede ham imellem Zora og Esthaol, hans Fader Manoas Grav; men han havde dømt Israel tyve Aar.',
    },
    17: {
        1: 'Og der var en Mand fra Efraims Bjerg, og hans Navn var Mika.',
        2: 'Og han sagde til sin Moder: De tusinde og hundrede Sekel Sølv, som ere tagne fra dig, og om hvilke du har udtalt en Forbandelse og sagt det endog i mit Paahør, se, det Sølv er hos mig, jeg har taget det; da sagde hans Moder: Velsignet være du, min Søn, for Herren!',
        3: 'Saa gav han sin Moder de tusinde og hundrede Sekel Sølv tilbage; og hans Moder sagde: Jeg har helliget Herren det Sølv fra min Haand for min Søn til at gøre et udskaaret og støbt Billede, derfor giver jeg dig det nu tilbage.',
        4: 'Men han gav sin Moder Sølvet tilbage; da tog hans Moder to Hundrede Sekel Sølv og gav Guldsmeden det, og han gjorde et udskaaret og støbt Billede deraf, og det var i Mikas Hus.',
        5: 'Og den Mand Mika havde et Guds Hus, og han gjorde en Livkjortel og Husguder og fyldte een af sine Sønners Haand, at han blev hans Præst.',
        6: 'I de samme Dage var ingen Konge i Israel; hver gjorde, hvad ret var for hans Øjne.',
        7: 'Og der var en ung Karl fra Bethlehem i Juda, af Judas Slægt; men han var en Levit, og han var fremmed der.',
        8: 'Men denne Mand gik fra Staden Bethlehem i Juda for at opholde sig, hvor han fandt Lejlighed; og han kom paa Efraims Bjerg til Mikas Hus for at fortsætte sin Vej.',
        9: 'Da sagde Mika til ham: Hvorfra kommer du? og han sagde til ham: Jeg er en Levit fra Bethlehem i Juda, og jeg gaar hen for at opholde mig, hvor jeg finder en Lejlighed.',
        10: 'Da sagde Mika til ham: Bliv hos mig, og bliv min Fader og Præst, saa vil jeg hvert Aar give dig ti Sekel Sølv og behørige Klæder og din Føde; og Leviten gik ind.',
        11: 'Og Leviten samtykkede i at blive hos Manden; og den unge Karl var ham som en af hans Sønner.',
        12: 'Og Mika fyldte Levitens Haand, og den unge Karl blev hans Præst; og han var i Mikas Hus.',
        13: 'Og Mika sagde: Nu ved jeg, at Herren skal gøre vel imod mig, efterdi jeg har en Levit til Præst.',
    },
    18: {
        1: 'I de samme Dage var ingen Konge i Israel, og i de samme Dage søgte Daniternes Stamme sig en Lod, hvor de kunde bo; thi der var indtil den Dag ikke tilfaldet dem nogen Arv iblandt Israels Stammer.',
        2: 'Og Dans Børn udsendte af deres Slægt fem Mænd af deres hele Tal, stridbare Mænd fra Zora og fra Esthaol for at bespejde Landet og at udforske det, og de sagde til dem: Gaar hen, udforsker Landet; og de kom paa Efraims Bjerg, til Mikas Hus, og bleve der om Natten.',
        3: 'Disse vare ved Mikas Hus, og disse kendte den unge Karls, Levitens Bøst, og de toge derind og sagde til ham: Hvo har ført dig herhid? og hvad gør du paa dette Sted? og hvad har du her?',
        4: 'Og han sagde til dem: Paa den og den Maade har Mika gjort imod mig, og han har lejet mig, og jeg er bleven hans Præst.',
        5: 'Og de sagde til ham: Kære, spørg Gud ad, at vi maa vide, om vor Vej, som vi vandre paa, skal blive lykkelig.',
        6: 'Og Præsten sagde til dem: Gaar med Fred! eders Vej, som I vandre paa, er for Herren.',
        7: 'Da gik de fem Mænd og kom til Lais; og de saa, at det Folk, som der var, boede tryggeligen, efter Zidoniernes Vis, roligt og trygt; og der var ingen, som lastede nogen Ting i Landet, eller som havde arvelig Magt; og de vare langt fra Zidonierne og havde intet at gøre med noget Menneske.',
        8: 'Og de kom til deres Brødre i Zora og Esthaol, og deres Brødre sagde til dem: Hvad sige I?',
        9: 'Og de sagde: Staar op og lader os drage op imod dem; thi vi have set Landet; og se, det er saare godt; og I tie? værer ikke lade til at gaa hen til at komme til at tage Landet til Eje.',
        10: 'Naar I komme, da skulle I komme til et trygt Folk, og Landet er vidt og bredt; thi Gud har givet det i eders Haand, et Sted, hvor der ikke er Mangel paa nogen Verdens Ting.',
        11: 'Da rejste derfra af Daniternes Slægt, fra Zora og Esthaol, seks Hundrede Mænd omgjordede med Krigsvaaben.',
        12: 'Og de droge op og lejrede sig i Kirjath-Jearim i Juda; derfor kaldte de det samme Sted Dans Lejr indtil denne Dag, se, den er bag Kirjath-Jearim.',
        13: 'Og de gik derfra over paa Efraims Bjerg, og de kom til Mikas Hus.',
        14: 'Da talte de fem Mænd, som vare gangne til at bespejde Landet Lais, og sagde til deres Brødre: Vide I, at i disse Huse er en Livkjortel og Husguder og et udskaaret og støbt Billede? derfor skønner nu, hvad I skulle gøre.',
        15: 'Og de toge derind og kom til den unge Karls, Levitens Hus, i Mikas Hus, og de hilsede ham.',
        16: 'Men de seks Hundrede Mænd, som vare omgjordede med deres Krigsvaaben, og som vare af Dans Børn, stode for Indgangen til Porten.',
        17: 'Og de fem Mænd, som vare udgangne til at bespejde Landet, gik op, de kom derhen, de toge det udskaarne Billede og Livkjortlen og Husguderne og det støbte Billede; og Præsten stod for Indgangen til Porten og de seks Hundrede Mænd, som vare omgjordede med Krigsvaaben.',
        18: 'Og der disse vare komne i Mikas Hus og havde taget det udskaarne Billede, Livkjortlen og Husguderne og det støbte Billede, da sagde Præsten til dem: Hvad gøre I?',
        19: 'Og de svarede ham: Ti, læg din Haand paa din Mund og gak med os, og vær vor Fader og Præst; er det bedre, at du er Præst for een Mands Hus, eller at du er Præst for en Stamme og for en Slægt i Israel?',
        20: 'Og Præstens Hjerte blev vel til Mode, og han tog Livkjortlen og Husguderne og det udskaarne Billede, og han kom midt iblandt Folket.',
        21: 'Og de vendte sig og gik bort; og de satte de smaa Børn og Kvæget, og hvad de havde at føre, foran.',
        22: 'Der de vare langt fra Mikas Hus, da bleve de Mænd, som vare i Husene ved Mikas Hus, sammenkaldte, og de indhentede Dans Børn.',
        23: 'Og de raabte til Dans Børn, og de vendte sig om, og de sagde til Mika: Hvad fattes dig, at du og de andre ere sammenkaldte?',
        24: 'Og han sagde: I have taget mine Guder, som jeg havde gjort, og Præsten, og I gaa bort; og hvad har jeg ydermere? hvi sige I da til mig: Hvad fattes dig?',
        25: 'Da sagde Dans Børn til ham: Lad din Røst ikke høres hos os, at de Mænd, som ere bitre i Sindet, ikke skulle anfalde eder, og du forspilde dit Liv og dit Folks Liv.',
        26: 'Saa gik Dans Børn deres Vej; og Mika saa, at de vare stærkere end han, og han vendte sig og kom tilbage til sit Hus.',
        27: 'Men de toge det, som Mika havde gjort, og Præsten, som han havde haft, og kom over Lais, over et roligt og trygt Folk, og sloge dem med skarpe Sværd; og de opbrændte Staden med Ild.',
        28: 'Og der var ingen, som friede den, thi den var langt fra Zidon, og de havde intet at gøre med noget Menneske; og den laa i Dalen, som er ved Beth-Rekob; saa byggede de Staden og boede derudi.',
        29: 'Og de kaldte Stadens Navn Dan, efter deres Fader Dans Navn, denne var en Søn af Israel; dog fra Begyndelsen var Stadens Navn Lais.',
        30: 'Og Dans Børn oprejste sig det udskaarne Billede; og Jonathan, en Søn af Gerson, Manasse Søn, var med sine Børn Præster for Daniternes Stamme, indtil den Dag, de flyttedes ud af Landet.',
        31: 'Saa satte de iblandt sig Mikas udskaarne Billede, som han havde gjort, alle de Dage, Guds Hus var i Silo.',
    },
    19: {
        1: 'Og det skete i de samme Dage, da der ingen Konge var i Israel, at der var en levitisk Mand, som opholdt sig som fremmed i de fjernere Egne af Efraims Bjerg og havde taget sig en Kvinde til Medhustru fra Bethlehem i Juda.',
        2: 'Og der hans Medhustru havde bedrevet Hor hos ham, da gik hun fra ham til sin Faders Hus, til Bethlehem i Juda; og hun blev der en fire Maaneders Tid.',
        3: 'Og hendes Mand gjorde sig rede og gik efter hende, at han vilde tale kærligen med hende for at føre hende tilbage, og han havde sin Dreng og et Par Asener med sig; og hun førte ham ind i sin Faders Hus, og der den unge Kvindes Fader saa ham, da blev han glad og gik ham i Møde.',
        4: 'Og hans Svigerfader, Kvindens Fader, holdt paa ham, at han blev hos ham i tre Dage; og de aade og drak og bleve der om Natten.',
        5: 'Og det skete paa den fjerde Dag, da stode de aarle op om Morgenen, og han gjorde sig rede til at gaa; da sagde den unge Kvindes Fader til sin Svigersøn: Vederkvæg dit Hjerte med et Stykke Brød, og derefter maa I gaa.',
        6: 'Og de satte sig og aade begge tilsammen og drak; da sagde den unge Kvindes Fader til Manden: Kære, samtyk, og bliv Natten over og lad dit Hjerte være vel til Mode.',
        7: 'Og Manden stod op for at gaa, og hans Svigerfader nødte ham, og han vendte tilbage og blev der om Natten.',
        8: 'Og han stod aarle op om Morgenen paa den femte Dag for at gaa, da sagde den unge Kvindes Fader: Kære, vederkvæg dit Hjerte; og de tøvede, indtil Dagen hældede, og de aade begge.',
        9: 'Og Manden stod op for at gaa, han og hans Medhustru og hans Dreng; men hans Svigerfader, den unge Kvindes Fader, sagde til ham: Se, kære, Dagen lider, og det bliver Aften, kære, bliver Natten over; se, Dagen er ad Ende, bliv her i Nat og lad dit Hjerte være vel til Mode, saa kunne I i Morgen staa aarle op for at gaa eders Vej, og du kan gaa til dit Telt.',
        10: 'Men Manden vilde ikke blive om Natten, men gjorde sig rede og gik bort og kom til tværs over for Jebus, det er Jerusalem; og et Par sadlede Asener vare med ham, og hans Medhustru var med ham.',
        11: 'Da de vare ved Jebus, hældede Dagen saare, og Drengen sagde til sin Herre: Kære, kom og lad os tage ind i denne Jebusiternes Stad og blive der i Nat.',
        12: 'Da sagde hans Herre til ham: Vi ville ikke tage ind i en fremmed Stad, som ikke tilhører Israels Børn; men vi ville gaa forbi til Gibea.',
        13: 'Og han sagde til sin Dreng: Gak frem, at vi kunne komme nær til een af Stæderne, og vi ville blive i Nat udi Gibea eller i Bama.',
        14: 'Og de gik forbi og vandrede, og Solen gik ned for dem, der de vare hart ved Gibea, som hører Benjamin til.',
        15: 'Og de toge ind der og kom for at blive Natten over i Gibea; og der han kom ind, da satte han sig paa Gaden i Staden; thi der var ingen, som annammede dem i Hus og lod dem blive hos sig om Natten.',
        16: 'Og se, der kom en gammel Mand fra sin Gerning fra Marken om Aftenen, og Manden var fra Efraims Bjerg, og han var en fremmed i Gibea, men Mændene paa det Sted vare Benjaminiter.',
        17: 'Og han opløftede sine Øjne og saa den vejfarende Mand paa Stadens Gade; da sagde den gamle Mand: Hvor vil du gaa hen, og hvorfra kommer du?',
        18: 'Og han sagde til ham: Vi gaa fra Bethlehem i Juda til de fjernere Egne af Efraims Bjerg, hvor jeg er fra, og jeg var gangen til Bethlehem i Juda; men jeg gaar til Herrens Hus, og der er ingen Mand, som annammer mig i Hus.',
        19: 'Og jeg har baade Straa og Foder til vore Asener, saa har jeg og Brød og Vin til mig og din Tjenestekvinde og til Drengen, som er med din Tjener; vi have ingen Mangel paa nogen Ting.',
        20: 'Og den gamle Mand sagde: Fred være med dig, lad ikkun, hvad du trænger til, være min Sag; bliv kun ikke Natten over paa Gaden.',
        21: 'Og han førte ham ind i sit Hus og gav Asenerne Foder; og de toede deres Fødder, og de aade og drak.',
        22: 'Der disse gjorde deres Hjerter til Gode, se, da omringede Mændene af Staden, Mænd, som vare Belials Børn, Huset, og bankede paa Døren; og de sagde til den gamle Mand, som var Husets Herre, sigende: Før den Mand ud, som kom i dit Hus, at vi kunne kende ham.',
        23: 'Men den Mand, som var Husets Herre, gik ud til dem, og sagde til dem: Ikke saa, mine Brødre, gører ikke ondt; efter at denne Mand er kommen i mit Hus, saa gører dog ikke denne Daarlighed!',
        24: 'Se, her er min Datter, som er Jomfru, og hans Medhustru; dem vil jeg udføre, og dem maa I krænke og gøre ved dem, hvad som godt er for eders Øjne; men gører ikke denne daarlige Gerning mod denne Mand!',
        25: 'Men Mændene vilde ikke høre ham; da tog Manden fat paa sin Medhustru og førte hende ud til dem udenfor; og de kendte hende og handlede skændeligen med hende den ganske Nat indtil om Morgenen, men der Morgenrøden gik op, lode de hende fare.',
        26: 'Da kom Kvinden, der Morgenen frembrød, og hun faldt ned for Døren af den Mands Hus, hvor hendes Herre var inde, indtil det blev lyst.',
        27: 'Og der hendes Herre stod op om Morgenen og oplod Dørene paa Huset og gik ud at vandre sin Vej, se, da var Kvinden, hans Medhustru, falden foran Husets Dør, og hendes Hænder laa paa Dørtærskelen.',
        28: 'Da sagde han til hende: Staa op og lad os vandre, men ingen svarede; da tog han hende op paa Asenet, og Manden gjorde sig rede og gik til sit Sted.',
        29: 'Og der han kom til sit Hus, da tog han en Kniv og tog fat paa sin Medhustru og huggede hende efter hendes Ben i tolv Stykker, og han sendte hende om til alt Israels Landemærke.',
        30: 'Og det skete, hver den, som saa det, sagde: Saadant er ikke sket eller set fra den Dag, Israels Børn droge op af Ægyptens Land, indtil denne Dag; tager dette til Hjerte, giver Raad og siger frem!',
    },
    20: {
        1: 'Da droge alle Israels Børn ud, og Menigheden blev samlet som een Mand, fra Dan indtil Beersaba og Landet Gilead, til Herren i Mizpa.',
        2: 'Og Høvdingerne for hele Folket, alle Israels Stammer, stillede sig frem i Guds Folks Forsamling: Fire Hundrede Tusinde Mand Fodfolk, som kunde føre Sværd.',
        3: 'Og Benjamins Børn hørte, at Israels Børn vare dragne op til Mizpa; og Israels Børn sagde: Siger, hvorledes er dette onde sket?',
        4: 'Da svarede den levitiske Mand, Manden til den Kvinde, som var ihjelslagen, og sagde: Jeg og min Medhustru kom til Gibea, som hører Benjamin til, for at blive der om Natten.',
        5: 'Og Mændene i Gibea stode op imod mig og omringede mig i Huset om Natten; de tænkte at ihjelslaa mig, og de have krænket min Medhustru, saa at hun er død.',
        6: 'Da tog jeg fat paa min Medhustru og huggede hende i Stykker og sendte hende om til al Israels Arvs Land; thi de have gjort en Skændsel og en Daarlighed i Israel.',
        7: 'Se, alle I ere Israels Børn; taler tilsammen og raadslaar her!',
        8: 'Da gjorde alt Folket sig rede som een Mand og sagde: Vi ville ikke, at nogen gaar til sit Telt, og at nogen viger herfra til sit Hus.',
        9: 'Men det er nu den Gerning, som vi ville gøre mod Gibea: Vi ville drage mod den efter Lodkastning.',
        10: 'Og vi ville tage ti Mænd af hundrede, af alle Israels Stammer, og hundrede af Tusinde, og tusinde af ti Tusinde, at de hente Tæring til Folket, at de kunne, naar de komme til Gibea i Benjamin, gengælde den al den Daarlighed, som den har gjort i Israel.',
        11: 'Saa bleve alle Israels Mænd samlede mod Staden; som een Mand vare de forbundne.',
        12: 'Og Israels Stammer sendte Mænd til alle Benjamins Slægter og lode sige: Hvad er dette for en Ondskab, som er sket iblandt eder?',
        13: 'Saa giver nu de Mænd hid, de Belials Børn, som ere i Gibea, at vi kunne slaa dem ihjel og borttage det onde af Israel; men Benjamins Børn vilde ikke høre deres Brødres, Israels Børns, Bøst.',
        14: 'Og Benjamins Børn bleve samlede fra Stæderne til Gibea, til at drage ud til Krigen mod Israels Børn.',
        15: 'Og Benjamins Børn fra Stæderne bleve samme Dag talte, seks og tyve Tusinde Mand, som kunde føre Sværd, foruden Indbyggerne i Gibea, som bleve talte, syv Hundrede udvalgte Mænd.',
        16: 'Iblandt alt dette Folk vare syv Hundrede udvalgte Mænd, som vare kejthaandede, af hvilke enhver slyngede med en Sten paa et Haar og fejlede ikke.',
        17: 'Men Mændene af Israel, foruden dem af Benjamin, bleve talte, fire Hundrede Tusinde Mand, som kunde føre Sværd; enhver af dem var Krigsmand.',
        18: 'Da gjorde de sig rede og droge op til Guds Hus og adspurgte Gud, og Israels Børn sagde: Hvo skal drage op for os at begynde Krigen mod Benjamins Børn? og Herren sagde: Juda skal begynde.',
        19: 'Saa gjorde Israels Børn sig rede om Morgenen, og de lejrede sig imod Gibea.',
        20: 'Og hver Mand af Israel gik ud til Krigen imod Benjamin, og hver Mand af Israel rustede sig til Krig mod dem, mod Gibea.',
        21: 'Da gik Benjamins Børn ud af Gibea, og de sloge af Israel paa den samme Dag to og tyve Tusinde Mand til Jorden.',
        22: 'Men Folket af Israels Mænd styrkede sig og stillede sig atter op til Slag paa det samme Sted, hvor de havde stillet sig op paa den første Dag.',
        23: 'Og Israels Børn droge op og græd for Herrens Ansigt indtil Aften, og de adspurgte Herren og sagde: Skal jeg ydermere blive ved at drage op til Krig mod Benjamins, min Broders, Børn? og Herren sagde: Drager op mod ham!',
        24: 'Og Israels Børn kom nær til Benjamins Børn paa den anden Dag.',
        25: 'Og Benjamin gik ud fra Gibea imod dem paa den anden Dag, og de sloge af Israels Børn endnu atten Tusinde Mænd til Jorden; alle disse kunde føre Sværd.',
        26: 'Da droge alle Israels Børn op, ja alt Folket, og kom til Guds Hus og græd og bleve der for Herrens Ansigt, og de fastede den samme Dag indtil Aften, og de ofrede Brændofre og Takofre for Herrens Ansigt.',
        27: 'Og Israels Børn adspurgte Herren; og Guds Pagts Ark var der i de Dage.',
        28: 'Og Pinehas, en Søn af Eleasar, Arons Søn, stod for hans Ansigt i de Dage og sagde: Skal jeg blive ved ydermere at drage ud til Krig imod Benjamins, min Broders, Børn, eller lade af? og Herren sagde: Drager op; thi i Morgen vil jeg give ham i din Haand.',
        29: 'Og Israel satte Baghold ved Gibea trindt omkring.',
        30: 'Saa droge Israels Børn op imod Benjamins Børn paa den tredje Dag, og de stillede sig op imod Gibea, som to Gange tilforn.',
        31: 'Da gik Benjamins Børn ud imod Folket, de droges bort fra Staden, og de begyndte at ihjelslaa nogle af Folket, som to Gange tilforn, paa de alfare Veje, af hvilke een løber op til Bethel og een til Gibea paa Marken, henved tredive Mand i Israel.',
        32: 'Da sagde Benjamins Børn: De ere slagne for vort Ansigt ligesom i Førstningen; men Israels Børn sagde: Lader os fly, at vi kunne drage ham bort fra Staden, paa de alfare Veje.',
        33: 'Da gjorde alle Israels Mænd sig rede af deres Sted og stillede sig op i Baal-Thamar, og Israels Baghold drog ud fra deres Sted, fra Hulen ved Geba.',
        34: 'Og ti Tusinde Mand, udvalgte af al Israel, kom tværs over for Gibea, og Krigen blev svar; men den vidste ikke, at det onde skulde ramme den.',
        35: 'Saa slog Herren Benjamin for Israels Ansigt, og Israels Børn sloge af Benjamin paa den samme Dag fem og tyve Tusinde og hundrede Mand; alle disse kunde føre Sværd.',
        36: 'Og Benjamins Børn saa, at de vare slagne; thi Israels Børn gave Benjamin Rum, fordi de forlode sig paa Bagholdet, som de havde lagt mod Gibea.',
        37: 'Og Bagholdet skyndte sig og faldt ind paa Gibea; og Bagholdet drog frem og slog den ganske Stad med skarpe Sværd.',
        38: 'Og Mændene af Israel havde gjort en bestemt Aftale med Bagholdet, at de skulde lade megen og høj Røg opgaa af Staden.',
        39: 'Da vendte Israels Mænd sig i Slaget, og Benjamin havde begyndt at ihjelslaa af Israels Mænd henved tredive Mand; thi de sagde: Visseligen han er slagen for vort Ansigt som i det første Slag.',
        40: 'Da begyndte en høj Røg, en Støtte af Røg, at stige op af Staden, og Benjamin saa om bag sig, og se, den hele Stad gik op i Røg mod Himmelen.',
        41: 'Og Israels Børn vendte sig, men Benjamins Mænd forfærdedes; thi de saa, at ondt vilde ramme dem.',
        42: 'Og de vendte sig for Israels Mænds Ansigt ad Vejen til Ørken, men Kampen indhentede dem; og de fra Stæderne nedhuggede dem midt imellem sig.',
        43: 'De omringede Benjamin, de forfulgte ham; hvor han hvilede, lode de ham nedtrædes, indtil tværs over for Gibea mod Solens Opgang.',
        44: 'Og der faldt af Benjamin atten Tusinde Mand; alle disse vare stridbare Mænd.',
        45: 'Da vendte de sig og flyede mod Ørken, til Klippen Rimmon, og hine sloge her og der paa de alfare Veje fem Tusinde Mand og forfulgte dem indtil Gideom, og de sloge af dem to Tusinde Mand.',
        46: 'Og alle de, som faldt af Benjamin, vare fem og tyve Tusinde Mand, som kunde føre Sværd, paa den Dag; alle disse vare stridbare Mænd.',
        47: 'Og seks Hundrede Mænd vendte sig og flyede mod Ørken til Klippen Rimmon; og de bleve paa Klippen Rimmon fire Maaneder.',
        48: 'Og Israels Mænd vendte tilbage til Benjamins Børn og sloge dem med skarpe Sværd, baade Folket af Stæderne og Kvæget, ja alt det, som fandtes; ogsaa alle Stæderne, som fandtes, satte de Ild paa.',
    },
    21: {
        1: 'Og Israels Mænd havde svoret i Mizpa og sagt: Der skal ingen af os give Benjamin sin Datter til Hustru.',
        2: 'Og Folket kom til Guds Hus, og de bleve der indtil Aftenen for Guds Ansigt; og de opløftede deres Røst og græd med en stor Graad.',
        3: 'Og de sagde: Herre, Israels Gud! hvorfor er dette sket i Israel, at i Dag een Stamme savnes af Israel?',
        4: 'Og det skete den anden Dag, da stod Folket aarle op, og de byggede der et Alter, og de ofrede Brændofre og Takofre.',
        5: 'Og Israels Børn sagde: Hvo er den, som ikke er kommen med op til Forsamlingen af alle Israels Stammer til Herren? Thi der var svoret en høj Ed imod den, som ikke kom op til Herren i Mizpa, saa der sagdes: Han skal visseligen dødes.',
        6: 'Og det gjorde Israels Børn ondt for deres Broder Benjamin, og de sagde: I Dag er een Stamme afhuggen af Israel.',
        7: 'Hvad ville vi gøre dem, som ere overblevne, at de kunne faa Hustruer? thi vi have svoret ved Herren, at vi ikke ville give dem af vore Døtre til Hustruer.',
        8: 'Og de sagde: Hvad er det for en af Israels Stammer, som ikke er kommen op til Herren i Mizpa? Og se, der var ingen Mand kommen til Lejren fra Jabes i Gilead til Forsamlingen.',
        9: 'Thi Folket blev talt; og se, da var der ingen af Indbyggerne fra Jabes i Gilead.',
        10: 'Da sendte de derhen af Menigheden tolv Tusinde Mand af Stridsfolkene; og de bøde dem og sagde: Gaar hen og slaar Indbyggerne i Jabes i Gilead med skarpe Sværd, samt Hustruerne og de smaa Børn.',
        11: 'Og denne er den Gerning, som I skulle gøre: Alt Mandkøn og alle Kvinder, som have haft Samkvem med nogen Mand, skulle I ødelægge.',
        12: 'Og de fandt af Indbyggerne i Jabes i Gilead fire Hundrede unge Piger, Jomfruer, som ikke havde kendt nogen Mand og ikke haft Samkvem med nogen Mand, og de førte dem til Lejren i Silo, som er i Landet Kanaan.',
        13: 'Da sendte den ganske Menighed hen, og de lode tale med Benjamins Børn, som vare paa Klippen Bimmon; og de tilbøde dem Fred.',
        14: 'Saa kom Benjamin tilbage paa samme Tid, og de gave dem de Hustruer, som de havde ladet leve af Kvinderne fra Jabes i Gilead; og de fandt ikke saaledes nok til dem.',
        15: 'Da gjorde det Folket ondt for Benjamin, fordi Herren havde gjort et Skaar i Israels Stammer.',
        16: 'Og Menighedens Ældste sagde: Hvad skulle vi gøre ved de overblevne, at de kunne faa Hustruer? thi Kvinderne af Benjamin ere udryddede.',
        17: 'Og de sagde: De undkomnes Ejendom skal høre Benjamin til, at ikke een Stamme skal blive udslettet af Israel.',
        18: 'Men vi kunne ikke give dem Hustruer af vore Døtre; thi Israels Børn have svoret og sagt: Forbandet være den, som giver Benjamin en Hustru!',
        19: 'Og de sagde: Se, der er Aar for Aar Herrens Højtid i Silo, som ligger Nord for Bethel, mod Solens Opgang, paa den alfare Vej, som gaar op fra Bethel til Sikem, og Syd for Lebona.',
        20: 'Og de befalede Benjamins Børn og sagde: Gaar hen og lurer i Vingaardene!',
        21: 'Og I skulle se til, og se, dersom Silos Døtre gaa ud at danse, da maa I gaa ud af Vingaardene og gribe eder hver sin Hustru af Silos Døtre, og I skulle gaa til Benjamins Land.',
        22: 'Og det skal ske, naar deres Fædre eller deres Brødre komme at gaa i Rette med os, da ville vi sige til dem: Værer dem naadige for vor Skyld, fordi vi ikke have skaffet dem hver sin Hustru i Krigen; thi I have heller ikke givet dem Hustruer; eller skulle I nu have været skyldige.',
        23: 'Og Benjamins Børn gjorde saaledes og toge Hustruer efter deres Tal af dem, som dansede, hvilke de røvede; og de gik og kom tilbage til deres Arv og byggede Stæderne og boede i dem.',
        24: 'Saa vandrede Israels Børn derfra paa samme Tid, hver til sin Stamme og til sin Slægt; og de udgik derfra, hver til sin Arv.',
        25: 'I disse Dage var ingen Konge i Israel; hver gjorde det, som var ret for hans Øjne.',
    },
}
